window.REALQ_N2_EXT = [
  // ==================== 文字・語彙（vocab）====================
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"ずっと好調だったのに、最後の試合で（敗れてしまった）。", passage:"", opts:["たおれて","やぶれて","みだれて","つぶれて"], ans:1, exp:"①「敗れる」读「やぶれる」，た形＝敗れた，即第2项，故正确。②考点：V2（下一段动词）读音＋同音异形字辨析——「敗れる（败）」与「破れる（撕破）」同读やぶれる，宾语是「試合」须用「敗れる」。③排除：1「たおれて」是倒れて（V2，倒下）；3「みだれて」是乱れて（V2，紊乱）；4「つぶれて」是潰れて（V2，被压坏），字形均不符。④译文：明明一直状态很好，却在最后一场比赛中（败下阵来）。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"この仕事には高い（語学力）が要求される。", passage:"", opts:["ようきゅ","よっきゅう","ようきゅう","よっきゅ"], ans:2, exp:"①「要求」读ようきゅう，即第3项，故正确。②考点：音读长音——「要」よう＋「求」きゅう；「求」在求人・請求中都读きゅう，长音不可丢。③排除：1「ようきゅ」丢长音；2「よっきゅう」是「欲求（よくきゅう）」的读法，汉字不同；4「よっきゅ」两处皆错。④译文：这份工作（要求）很高的外语能力。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"友達の（合格）をみんなで祝った。", passage:"", opts:["いわった","いのった","うちなった","ねがった"], ans:0, exp:"①「祝う（いわう）」的た形＝祝った，即第1项，故正确。②考点：V1（五段动词）た形音便——词尾「う」接「た」发生促音便（わ＋った）；同时考查同音汉字。③排除：2「いのった」是祈った（祈祷，祈る）；3「うちなった」无此词；4「ねがった」是願った（请求，願う），汉字不同。④译文：大家一起（庆祝）了朋友考试合格。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"寒かったら、エアコンの（温度）を調節してください。", passage:"", opts:["ちょうさい","ちょうせい","ちょうさつ","ちょうせつ"], ans:3, exp:"①「調節」读ちょうせつ，即第4项，故正确。②考点：音读——「調」ちょう＋「節」せつ（季節・節約的節也读せつ）；须与「調整（ちょうせい）」区分。③排除：1「ちょうさい」把節误读成さい；2「ちょうせい」是「調整」的读音，汉字为「整」；3无此词。④译文：冷的话请把空调温度（调节）一下。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"この書類を（至急）コピーしてきてください。", passage:"", opts:["しっきゅ","ちっきゅう","しきゅう","ちきゅう"], ans:2, exp:"①「至急」读しきゅう，即第3项，故正确。②考点：音读——「至」し（至上）＋「急」きゅう，既无促音也无浊音；注意「早急」读そうきゅう。③排除：1「しっきゅ」多出促音且丢长音；2「ちっきゅう」把至误读成ち；4「ちきゅう」是「地球」的读音。④译文：请把这份文件（马上）复印了拿来。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"ハトは（平和）のしょうちょうだと言われている。", passage:"", opts:["像徵","象微","象徴","像微"], ans:2, exp:"①「しょうちょう」＝象徴，即第3项，故正确。②考点：汉字字形——「象」しょう（現象・印象）＋「徴」ちょう（特徴）。③排除：1用「像」（ぞう，銅像）错；2用「微」（び，微妙），形近而字不同；4两字皆错。④译文：据说鸽子是（和平的象征）。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"退院しても、しばらくの間は（げしい）運動はしないでください。", passage:"", opts:["険しい","激しい","暴しい","極しい"], ans:1, exp:"①「はげしい」＝激しい，即第2项，故正确。②考点：形近字辨析——「激しい運動」（剧烈运动）是固定搭配。③排除：1「険しい」读けわしい（险峻），读音不符；3「暴しい」无此形容词（有暴れる・乱暴）；4「極しい」无此词（極端・極める）。④译文：出院后一段时间请不要做（剧烈）运动。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"携帯電話に友達の電話番号を（とうろく）した。", passage:"", opts:["登録","登緑","答録","答緑"], ans:0, exp:"①「とうろく」＝登録，即第1项，故正确。②考点：汉字——「登」とう（登山・登場）＋「録」ろく（記録・録音）。③排除：2「緑」读りょく/みどり，形近「録」但字不同；3「答」读とう（回答）但词义不通；4两字皆错。④译文：把朋友的电话号码（登录）进手机了。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"岡田さんを（話題）の映画にさそった。", passage:"", opts:["招った","勧った","請った","誘った"], ans:3, exp:"①「さそう」对应汉字「誘った」，即第4项，故正确。②考点：V1（五段・う行）「誘う（さそう）」的他动词词义——「〜に誘う」（邀约某人做某事）。③排除：1「招った」是招く（まく）的た形，读音不合；2「勧った」来自勧める（すすめる，V2）；3「請った」读こう/うける，与さそう无关。④译文：我（邀请）岡田去看热门电影。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"待ち合わせの時間を6時に（へんこう）してもらった。", passage:"", opts:["変改","変更","変換","変替"], ans:1, exp:"①「へんこう」＝変更，即第2项，故正确。②考点：汉语动词与宾语的固定搭配——「時間を変更する」（变更时间）。③排除：1「変改」不是词（改读かい，改正）；3「変換」读へんかん（转换，如データを変換する）；4「変替」不是词（交替・替える）。④译文：（把）碰头时间（改）到6点了。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"彼は医学（ ）ではかなり知られた存在だ。", passage:"", opts:["界","帯","域","区"], ans:0, exp:"①「医学界」＝医学界（圈子），即第1项，故正确。②考点：接尾词「N＋界（かい）」表示某领域的人群/圈子（政界・財界・芸能界・学界）。③排除：2「〜帯」是地带（熱帯・時間帯）；3「〜域」是区域（地域・領域）；4「〜区」是行政区（新宿区），都不表示人群圈子。④译文：他在（医学界）是相当知名的人物。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"決勝戦で負けて、（ ）優勝に終わった。", passage:"", opts:["後","準","次","副"], ans:1, exp:"①「準優勝」＝亚军，即第2项，故正确。②考点：接头词「準〜（じゅん）」＝次于…的、亚（準優勝・準決勝・準教授）。③排除：1「後優勝」不成立；3「次優勝」不是词（次〜表「下一个」，次回・次年度）；4「副〜」是副手（副社長），不表比赛名次。④译文：决赛输了，最终获得（亚）军。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"（ ）段階では詳細は決まっていないらしい。", passage:"", opts:["現","直","近","当"], ans:0, exp:"①「現段階」＝现阶段，即第1项，故正确。②考点：接头词「現〜（げん）」＝当前的（現段階・現時点・現社長・現状）。③排除：2「直〜」用于直前・直後（紧接前后）；3「近段階」不成立（近〜用于近日・近代）；4「当〜」是文书语「本、该」（当社・当日），不与段階搭配。④译文：（现阶段）细节似乎还没定。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"今回の大臣の訪問は（ ）公式に行われた。", passage:"", opts:["不","末","無","非"], ans:3, exp:"①「非公式」＝非正式，即第4项，故正确。②考点：否定接头词「不／無／未／非」各有固定搭配——「公式」固定配「非」（非公式・非公開・非常識）。③排除：1「不公式」不成立（不〜配不正確・不必要）；2「末」是末尾（月末）；3「無公式」不是词（無〜配無理・無断）。④译文：此次大臣的访问是以（非正式）形式进行的。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"わが社の今年の（ ）売上は昨年を上回った。", passage:"", opts:["集","総","合","満"], ans:1, exp:"①「総売上」＝总销售额，即第2项，故正确。②考点：接头词「総〜（そう）」＝总计（総売上・総額・総人口・総合）。③排除：1「集売上」不成立（〜集构成作品集）；3「合売上」不成立（合計才是「合计」）；4「満〜」是满（満員・満足），不与売上搭配。④译文：我司今年的（总）销售额超过了去年。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"さまざまなデータを（ ）した結果、事故の原因が明らかになった。", passage:"", opts:["視察","検査","発明","分析"], ans:3, exp:"①「データを分析する」＝分析数据，即第4项，故正确。②考点：N＋する构成的他动词与宾语搭配——分析＝把整体拆解为要素寻找规律。③排除：1「視察」是视察现场（工場を視察する）；2「検査」是检查是否合格（品質検査・健康診断）；3「発明」是发明，宾语应是制品或方法。④译文：（分析）了各种数据后，事故原因水落石出。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"町を（ ）していたら、山本さんに会った。", passage:"", opts:["ぐらぐら","がらがら","ばらばら","ぶらぶら"], ans:3, exp:"①「町をぶらぶらする」＝在街上闲逛，即第4项，故正确。②考点：Adv拟态副词辨析——ぶらぶら＝无目的地走动。③排除：1「ぐらぐら」是摇晃（牙松了、桌子不稳）；2「がらがら」是空无一人或哗啦哗啦的响声；3「ばらばら」是零散、各自分开（意見がばらばらだ）。④译文：我正在街上（闲逛），碰见了山本。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"祭りの日は町が（ ）にあふれている。", passage:"", opts:["活気","活発","活躍","活動"], ans:0, exp:"①「活気にあふれる」＝充满活力，即第1项，故正确。②考点：N＋にあふれる的搭配——需要抽象名词「活気（かっき）」。③排除：2「活発」是A2（な形容词，活発な議論），不能直接＋にあふれる；3「活躍」是人的出色表现（選手の活躍）；4「活動」是活动过程，城市不能「活动にあふれる」。④译文：祭典那天街上（充满活力）。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"コピー機に紙が（ ）、出てこない。", passage:"", opts:["もぐって","つまって","しずんで","うまって"], ans:1, exp:"①「紙が詰まる」＝卡纸，即第2项，故正确。②考点：自动词与主语的搭配——詰まる（つまる，V1五段）＝堵塞、卡住。③排除：1「もぐる」是潜入（V1，水にもぐる）；3「沈む」是下沉（V1）；4「埋まる」是被填满（V1），都不用于机器卡纸。④译文：复印机（卡）纸了，出不来。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"この小説は今の時代を（ ）した作品だ。", passage:"", opts:["反映","放映","引用","採用"], ans:0, exp:"①「時代を反映する」＝反映时代，即第1项，故正确。②考点：N＋する动词的惯用搭配——反映＝作品映照出现实。③排除：2「放映」是电视播出（ドラマを放映する）；3「引用」是引用他人的话（〜を引用する）；4「採用」是采纳意见或录用人员（意見を採用する）。④译文：这部小说是（反映）当今时代的作品。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"田中さんは長い間（ ）窓の外を見ていた。", passage:"", opts:["ぼんやり","ふんわり","うっすら","しっとり"], ans:0, exp:"①「ぼんやり窓の外を見る」＝发呆地望着窗外，即第1项，故正确。②考点：Adv词义——ぼんやり＝心不在焉、茫然（也可表影像模糊）。③排除：2「ふんわり」是轻柔蓬松（口感、云朵）；3「うっすら」是隐约（うっすら雪が積もる）；4「しっとり」是温润柔和（しっとりした肌・曲）。④译文：田中（愣愣地）望着窗外看了很久。", t:""},
  {type:"vocab", src:"N2官方样题·公式問題集Vol.1（rostovjapan公开整理）", q:"経済だけでなく、法律にも詳しいのが彼の（ ）だ。", passage:"", opts:["深み","強み","高み","重み"], ans:1, exp:"①「彼の強みだ」＝是他的强项，即第2项，故正确。②考点：N＋み构成的抽象名词辨析——強み＝长处、强项（弱み的反义）。③排除：1「深み」是深度、韵味；3「高み」是高度、高水平（高みの見もの）；4「重み」是重量、分量，都不能概括「既懂经济又懂法律」这一长处。④译文：不仅懂经济，还精通法律，这是他的（长处）。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"美しい（情景）が目に浮かんだ。", passage:"", opts:["じょうけい","じょけい","じょうえい","じょえい"], ans:0, exp:"①「情景」读じょうけい，即第1项，故正确。②考点：音读——「情」じょう（拗长音）＋「景」けい（風景・背景同）。③排除：2「じょけい」丢了长音；3「じょうえい」把景误读成えい；4两处皆错。④译文：美丽的（情景）浮现在眼前。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"とても（和やか）なパーティーだった。", passage:"", opts:["おだやか","さわやか","なごやか","にぎやか"], ans:2, exp:"①「和やか」读なごやか，即第3项，故正确。②考点：A2（な形容词）读音——和（なご）＋やか，表气氛融洽。③排除：1「おだやか」对应穏やか（平静）；2「さわやか」对应爽やか（清爽）；4「にぎやか」对应賑やか（热闹），都是别的词。④译文：那是一场非常（融洽）的聚会。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"今後は（ふくし）の仕事に就く予定です。", passage:"", opts:["福支","副祉","福祉","副支"], ans:2, exp:"①「ふくし」＝福祉（福利），即第3项，故正确。②考点：汉字——「福」ふく＋「祉」し（福祉・社会福祉）；注意「祉」与「支」形近。③排除：1「福支」不是词；2「副祉」首字错（副读ふく，副社長）；4两字皆错。④译文：今后打算从事（福利）方面的工作。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"落ち葉がつもった道を歩いた。", passage:"", opts:["詰もった","満もった","占もった","積もった"], ans:3, exp:"①「積もる（つもる）」＝堆积，过去式積もった，即第4项，故正确。②考点：V1（五段・ろ行）自动词的汉字表记——「積もる」（落叶堆积）。③排除：1「詰もる」无此词（詰まる）；2「満もる」无此词（満ちる）；3「占もる」无此词（占める）。④译文：走在（堆满）落叶的路上。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"坂本さんは（かいご）の仕事をしている。", passage:"", opts:["看穫","介護","介種","看護"], ans:1, exp:"①「かいご」＝介護（护理），即第2项，故正确。②考点：汉字——「介」かい＋「護」ご（保護・守護）；与「看護（かんご）」的读音区分。③排除：1无此词；3「介種」错字；4「看護」读かんご，与かいご读音不符。④译文：坂本在做（护理）方面的工作。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"出張後、費用の（せいさん）をした。", passage:"", opts:["請算","製算","精算","制算"], ans:2, exp:"①「せいさん」＝精算（结算），即第3项，故正确。②考点：汉字——「精」せい（精神・精密）＋「算」さん；差旅费精算为固定说法。③排除：1「請算」不成立（請读しん/うける）；2「製算」不成立（製造）；4「制算」不成立（制度）。④译文：出差回来后（结算）了费用。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"友達だと思っていたのに、私のいないところで（ ）と私の悪口を言っていた。", passage:"", opts:["うとうと","こそこそ","ぶるぶる","じろじろ"], ans:1, exp:"①「こそこそと悪口を言う」＝鬼鬼祟祟地说坏话，即第2项，故正确。②考点：Adv拟态词——こそこそ＝偷偷摸摸、背地里。③排除：1「うとうと」是迷迷糊糊（打瞌睡）；3「ぶるぶる」是发抖或抖动；4「じろじろ」是上下打量，都不能修饰「背后说坏话」。④译文：明明当他是朋友，却在我不在时（鬼鬼祟祟）地说我坏话。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"今日の海は波が高く、船が揺れたせいで、気分が悪くなる人が（ ）した。", passage:"", opts:["続行","続出","持続","継続"], ans:1, exp:"①「人が続出する」＝（这样的人）接连出现，即第2项，故正确。②考点：N＋する动词——続出＝接连不断地出现（被害者・応募者が続出する）。③排除：1「続行」是继续进行（雨天決行・続行）；3「持続」是状态延续（効果が持続する）；4「継続」是接着做下去，都不表示「接连出现」。④译文：今天海浪大，因为船颠簸，（接连）有人觉得恶心。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"この建物を壊すのは（惜しい）。", passage:"", opts:["危ない","もったいない","めんどうくさい","難しい"], ans:1, exp:"①「惜しい」＝もったいない（可惜、可惜得浪费），即第2项，故正确。②考点：A1（い形容词）的言い換え——惜しい＝不该糟蹋、可惜。③排除：1「危ない」＝危险；3「めんどうくさい」＝麻烦；4「難しい」＝难，都不含「可惜」义。④译文：拆掉这栋楼太（可惜）了。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"説明が（くどくて）すみません。", passage:"", opts:["つまらなくて","下手で","複雑で","しつこくて"], ans:3, exp:"①「説明がくどい」＝说明冗长啰嗦，くどくて＝しつこくて，即第4项，故正确。②考点：A1词义＋て形接续——くどい（冗长重复）近义于しつこい。③排除：1「つまらない」＝无聊；2「下手（A2）」＝笨拙，须接「に」（下手に話す）；3「複雑」＝复杂，都不表「啰嗦」。④译文：（说明太啰嗦了），不好意思。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"この表現は（修正した）ほうがいいですよ。", passage:"", opts:["調べた","覚えた","直した","使った"], ans:2, exp:"①「修正する」＝修改、改正，近义词「直す（なおす）」，即第3项，故正确。②考点：言い換え（同义替换）——「〜たほうがいい」建议句中的动词语义。③排除：1「調べた」＝查证；2「覚えた」＝记住；4「使った」＝使用，都不含「改过来」之意。④译文：这个表达你（改一下）比较好哦。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"私の会社は（最寄り）の駅から歩いて15分です。", passage:"", opts:["一番大きい","一番近い","終点の","始発の"], ans:1, exp:"①「最寄り（もより）の駅」＝最近的车站，即「一番近い」，第2项，故正确。②考点：言い換え——最寄り＝离此地最近的（车站・場所）。③排除：1与大小无关；3「終点の」是终点站；4「始発の」是始发站，都不是「最近」。④译文：我公司在（离得最近的）车站步行15分钟处。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"「定年」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["私の会社は60歳が定年なので、あと半年で退職だ。","この乗り物は子ども向けなので、10歳が定年になっている。","この国では、定年の20歳になると選挙で投票することができる。","犬の定年は一般的に10歳から15歳の間だといわれている。"], ans:0, exp:"①「定年（ていねん）」＝退休年龄，「会社は60歳が定年」是唯一正确用法，第1项正确。②考点：N的使用范围——定年专指人的退休年龄（定年退職・定年制）。③排除：2儿童乘车的年龄限制应说「対象年齢／10歳まで」；3投票年龄应说「選挙年齢」；4动物没有退休概念，应说「寿命」。④译文（正确项）：我们公司60岁（退休），所以我还有半年就要离职了。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"「急激」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["イベントの開催日が近くなり、準備が急激に進められている。","新しい駅ができて、市の人口が急激に増加している。","このパンは非常に人気があり、朝8時に開店すると急激に売れていく。","松田選手が現れると、ファンの人たちが急激に取り囲んだ。"], ans:1, exp:"①「急激に増加する」＝急剧增加，数量/程度的大幅快速变化正是「急激」的典型对象，第2项正确。②考点：Adv「急激（きゅうげき）」＋动词的搭配限制。③排除：1进度应说「急いで／大幅に進められている」；3刚开店就畅销应说「あっという間に次々と売れていく」；4人群围上来应说「一斉に／殺到した」。④译文（正确项）：新站建成后，市人口（急剧）增加。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"「欠陥」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["あの人の欠陥は、自分に都合の悪いことがあるとうそをつくことだ。","眼鏡のレンズを硬い布でふいたら、欠陥がついてしまった。","先月発表された車のブレーキに欠陥が見つかり、販売が中止された。","このサービスを利用することの欠陥は費用が非常にかかることだ。"], ans:2, exp:"①「ブレーキに欠陥が見つかる」＝发现刹车存在缺陷，欠陥指产品/构造上的瑕疵，第3项正确。②考点：N「欠陥（けっかん）」＝设计制造上的毛病，常配「〜に欠陥がある／欠陥品」。③排除：1人的缺点应说「欠点」；2镜片上的划痕应说「キズ」；4费用高是「欠点／デメリット」，不是欠陥。④译文（正确项）：上月发布的汽车刹车被查出（缺陷），已停售。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"「充満」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["この図書館は、あらゆる分野の本が充満していて、とても便利だ。","このコンサートは人気があって、常に観客が充満している。","部屋に食べ物の強いにおいが充満していたので、窓を開けた。","夢が充満している子どもたちが大好きで、小学校の教師になった。"], ans:2, exp:"①「部屋ににおいが充満していた」＝屋里弥漫着食物气味，充満＝气体或氛围充满空间，第3项正确。②考点：N＋が充満する的搭配——对象须是弥漫空间的气体/氛围类（自信が充満する・危機感が充満する）。③排除：1书应说「本が集まっている／揃っている」；2观众应说「観客でいっぱい」；4梦想应说「夢にあふれている」。④译文（正确项）：屋里（充满）浓烈的食物气味，所以我开了窗。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"「多彩」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["高橋氏は、小説家や画家として多彩な活動を行っている。","今夜は空に星が多彩に輝いていて、とてもきれいです。","文章にあいまいな表現を使うと、読者が多彩な理解をするだろう。","木村さんには生活全般において多彩にお世話になりました。"], ans:0, exp:"①「多彩な活動を行う」＝开展丰富多彩的活动，多彩＝形式多样，第1项正确。②考点：A2（な形容词）「多彩（たさい）」的搭配——修饰活动、内容、組み合わせ等。③排除：2星星应说「キラキラと／まばゆく輝く」；3理解应说「いろいろな解釈」；4受照顾应说「いろいろ／多方面にお世話になった」。④译文（正确项）：高桥氏以小说家、画家等（多样）身份开展活动。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"「鮮明」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["次回のセミナーの開催日はまだ鮮明に決まっていない。","できそうにない仕事は鮮明に断ったほうがいい。","B社の製品のほうが性能が鮮明に優れている。","あのときの出来事は今でも鮮明に覚えている。"], ans:3, exp:"①「あのときの出来事は今でも鮮明に覚えている」＝至今仍（清晰）记得，鮮明＝清晰鲜明，第4项正确。②考点：A2「鮮明（せんめい）」与名词的搭配——印象・記憶・色合いを鮮明に（する）。③排除：1日程应说「はっきり／具体的に決まっていない」；2拒绝应说「きっぱり／はっきり断る」；3性能优越应说「明らかに／ずっと優れている」。④译文（正确项）：那时候的事我至今（清晰）记得。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"「傾向」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["ファッション誌によると、今年は黄色が傾向するそうだ。","最近では、家族がばらばらに食事をする傾向がある。","姉は日本文学の研究に傾向している。","この坂は傾向がきっくて、自転車だとつらい。"], ans:1, exp:"①「食事をばらばらにする傾向がある」＝有各自吃饭的倾向，「N＋が〜傾向がある」是标准用法，第2项正确。②考点：N「傾向（けいこう）」的句型——傾向がある／傾向にある。③排除：1应说「黄色が人気らしい」；3应说「研究に打ち込んでいる／傾いている」；4坡度陡应说「傾きがきっくて」，不能说「傾向がきい」。④译文（正确项）：最近有家人各自吃饭的（倾向）。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"「早期」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["夏休みの早期は旅行をして、その後は試験勉強をする予定だ。","明日の機は早期の便だから、朝5時に家を出なければならない。","一人暮らしの早期は、料理などの失敗も多くて苦労した。","医療の進歩によって、病気を早期の段階で見つけられるようになった。"], ans:3, exp:"①「病気を早期の段階で発見する」＝早期发现，早期＝事情开始后的初期阶段且多用于病気・対策，第4项正确。②考点：N「早期（そうき）」的搭配——早期発見・早期対応・早期の段階。③排除：1应说「夏休みの初め／前半」；2应说「早朝の便」；3应说「一人暮らしの当初／はじめ」。④译文（正确项）：由于医疗进步，（早期）阶段就能查出疾病了。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"「漏れる」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["ジュースを注ぎすぎて、コップから漏れてしまった。","転んでしまって、ひざから血が漏れてきた。","水道管に穴があいているのか、水が漏れてきている。","悲しい映画を見たせいで、涙が漏れてきた。"], ans:2, exp:"①「水道管から水が漏れる」＝水管漏水，漏れる（もれる，V2自动词）指液体从孔隙渗出，第3项正确。②考点：V2自动词与主语的搭配。③排除：1容器溢出应说「こぼれた」；2伤口流血应说「血が出てきた」；4流泪应说「涙がこぼれた」。④译文（正确项）：可能是水管有孔，（漏）出水来了。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"「ぎっしり」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["大きな箱に本がぎっしり詰まっている。","ジュースがコップにぎっしり入っている。","少し太ったせいで、ズボンがぎっしりしている。","朝の電車はいつも人でぎっしりしている。"], ans:0, exp:"①「箱に本がぎっしり詰まっている」＝箱子里塞满书，ぎっしり＝固体塞得满满当当，第1项正确。②考点：Adv拟态词——ぎっしり修饰「詰まる／入っている」且对象须为固形物。③排除：2液体应说「いっぱい」；3应说「（きついで）ぴったり／きつい」；4应说「人がぎっしり詰まっている／混んでいる」，「人でぎっしりしている」不自然。④译文（正确项）：大箱子里（塞满）了书。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"「めくる」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["この小説は面白くて、次のページをめくるのが楽しみだった。","汗をかいたので、タオルを水でぬらし、きつくめくって体をふいた。","封筒に書類を入れ、開かないように丁寧にのりでめくっておいた。","そのドアは押すのではなくて手前にめくらないと開きませんよ。"], ans:0, exp:"①「ページをめくる」＝翻页，めくる（V1五段）＝掀开薄片状物，第1项正确。②考点：V1他动词与宾语的搭配——本のページ・カレンダー・ページをめくる。③排除：2拧毛巾应说「ねじって」；3粘贴应说「貼って／封をして」；4开抽屉、门应说「引っぱる／開ける」，めくる不用于门。④译文（正确项）：这小说很有趣，（翻）下一页很让人期待。", t:""},
  {type:"vocab", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"「乗り継ぐ」——次の1～4の中で、この言葉の使い方として最もよいものを一つ選びなさい。", passage:"", opts:["居眠りをして、降りるつもりだった駅を乗り継いでしまった。","疲れたので友達に運転を乗り継いでもらった。","バスと電車を乗り継いで、やっと目的地に着いた。","朝はたくさんの人が電車を乗り継ぐので、ドアの近くに立っていると大変だ。"], ans:2, exp:"①「バスと電車を乗り継ぐ」＝换乘公交和电车，乗り継ぐ（V1）＝中途改乘另一种交通工具，第3项正确。②考点：V1与宾语搭配——電車・バスを乗り継ぐ（乗り継ぎ駅）。③排除：1坐过站应说「乗り過ごす」；2交接驾驶应说「運転を引き継ぐ」；4「乗り継ぐからドアの近くに立つ」因果不通，换乘拥挤应说「踏み換え客で混雑する」。④译文（正确项）：换乘公交和电车，好不容易到了目的地。", t:""},

  // ==================== 文法（gram）====================
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"睡眠には、体や脳にたまった疲労をとる効果がある。睡眠時間を削ることは、体や脳を回復させる大切な機会を奪うことに（ ）のだ。", passage:"", opts:["ほかならない","欠かせない","すぎない","限らない"], ans:0, exp:"①「～ことにほかならない」＝无非就是…，句意为「削减睡眠时间无非是剥夺了恢复身心的宝贵机会」，第1项正确。②考点：接续——N＋ことにほかならない（书面断定语气）。③排除：2「欠かせない」＝不可或缺，「機会を奪うことに欠かせない」不通；3「すぎない」＝不过是，前须接「一つの手段」类名词，且与「のだ」的断定语气冲突；4「限らない」＝不限于，与句义相反。④译文：睡眠有消除身心积劳的功效。削减睡眠时间，（无非就是）剥夺了恢复身心的宝贵机会。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"今日の試合は大雪で延期になった。（ ）この時期に大雪になるとは思わなかった。", passage:"", opts:["一体","二度と","まさか","かえって"], ans:2, exp:"①「まさか＋～とは思わなかった」＝万万没想到，第3项正确。②考点：Adv「まさか」与否定性意外判断呼应（まさか～とは思わない／まさか～ないだろう）。③排除：1「一体（全体）」用于质问「到底为什么」，须配疑问词；2「二度と」＝再也不，须接动词否定且表意志性不再做；4「かえって」＝反而，前后无反向关系。④译文：今天比赛因大雪延期。真（没想到）这个时期会下大雪。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"カレーを大量に作りすぎて、一人では食べ（ ）と思ったので、友人をよんで食べた。", passage:"", opts:["切れるかもしれない","切れそうにない","かねないだろう","かねないようだ"], ans:1, exp:"①「食べ切れそうにない」＝好像吃不完，第2项正确。②考点：接续——V1可能形（食べ切る）＋そうにない（様態的否定，看上去不会…），故用辞書形「食べ切れそうにない」。③排除：1「食べ切れるかもしれない」是肯定推测，与「叫朋友来吃」的应对不搭；3「かねない」表负面担忧（失敗しかねない），与「食べる」不搭配；4同理且「ようだ」双重推测冗余。④译文：咖喱做太多了，觉得一个人（吃不完），就叫朋友一起来吃。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"毎日日記を書き続けることは、（ ）、けっこう難しいことだ。", passage:"", opts:["簡単らしいし","簡単なようであれば","簡単らしくて","簡単なようでいて"], ans:3, exp:"①「簡単（A2）なようでいて」＝看似简单实则…，表表面与实际的转折，第4项正确。②考点：接续——A2（だ→で）＋ようでいて（＝简单そうに見えて）。③排除：1「らしい」是传闻/推测，与后句转折不成立；2「ようであれば」是假定，后句应接建议；3「らしくて」把A2误当A1（「簡単」是A2，应为「で」）。④译文：每天坚持写日记，（看似简单），其实挺难。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"梅雨に入ってもほとんど雨が降らないので、庭の花が（ ）心配だ。", passage:"", opts:["枯れていないことで","枯れてしまわないか","枯れていないからと","枯れてしまわないのを"], ans:1, exp:"①「枯れてしまわないか心配だ」＝担心会不会枯掉，第2项正确。②考点：接续——V1/V2/V3未然形（枯れてしまわない）＋か＋心配だ／不安だ（～ないかと心配する）。③排除：1「ことで」须接因果表达，与「心配だ」接不上；3「からと」需后接「心配して」等引用；4「のを」须接「心配している（内容）」的宾语结构，直接接心配だ不成立。④译文：梅雨季节也几乎不下雨，很（担心）院子里的花会不会枯掉。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"あの人は、人の意見を聞き（ ）しないで、自分の主張ばかりする。", passage:"", opts:["まで","も","と","を"], ans:1, exp:"①「聞きもしないで」＝连听都不听，第2项正确。②考点：助词「も」＋否定的强调用法——V1/V2/V3ます形去ます＋も＋ない（考えもしない・見てもみない）。③排除：1「まで」表程度上限（～までできる），「聞きまでしないで」不通；3「と」须接「と言う」类引用；4「を」与前面的「聞き」重复成「聞きをしないで」，格助词冲突。④译文：那个人（连）别人的意见（都）不听，只顾主张自己。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"12月に入り、インフルエンザの患者数は増える（ ）。", passage:"", opts:["ほとど","までだ","一方だ","次第だ"], ans:2, exp:"①「増える一方だ」＝不断（单向）增加，第3项正确。②考点：接续——V1辞書形＋一方だ（多接悪化・増える等消极变化）。③排除：1「ほとんど」须接否定（ほとんど増えない），与句尾矛盾；2「までだ」＝到…为止/只要…就行，语义不通；4「次第だ」须接て形或名词（人気次第だ／決まり次第）。④译文：进入12月，流感患者数（不断）增加。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"私は両親に子供のころから自分がやりたいことを自由に（ ）。", passage:"", opts:["やらせてもらってくる","やらせてくれている","やらせてもらってきた","やらせてくれていた"], ans:2, exp:"①「やらせてもらってきた」＝（从过去起）一直蒙受父母允许我做…，第3项正确。②考点：接续——V1/V2/V3未然形（やら）＋させて＋もらう＋てきた（使役＋授受＋自过去持续至今）。③排除：1「～てくる」表从现在向将来持续，与「子供のころから」的回顾视角不符；2、4「～てくれる」的给予方向是「父母给我」，但格助词是「両親に」，须用「～てもらう」的句式。④译文：我从小时候起，父母就（允许我）自由地做自己想做的事。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 1（jlpt247整理）", q:"客：「すみません、『山の中で』っていう本を探しているんですけど。」店員：「はい、新刊コーナーに（ ）。ご案内します。」", passage:"", opts:["いたします","おります","ございます","なさいます"], ans:2, exp:"①「新刊コーナーにございます」＝（书）在新刊区，ございます是「ある」的丁寧・尊敬表达，第3项正确。②考点：敬语——「ある」→「ございます」；对客人描述物/人所在用「ございます」。③排除：1「いたします」是する的自谦，不能表存在；2「おります」是いる的自谦（主体须是自己一方）；4「なさいます」是する的尊敬语，主体应是客人的行为。④译文：在新刊区。（我）带您过去。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"約束の時間に友人の家に着いてインターホンを押すと、慌てた様子で友人が玄関に出てきた。（ ）、パジャマ姿のままだった。", passage:"", opts:["起きるところだったら","起きるところらしく","起きたばかりだったら","起きたばかりらしく"], ans:3, exp:"①「起きたばかりらしく」＝一副刚起床的样子，第4项正确。②考点：接续——V1/V2/V3た形＋ばかり（刚…）＋様態の「らしく」（～という様子で）。③排除：1、3「～だったら」是假定形，不能接描述性的「らしく」；2「起きるところらしく」＝正要起床，与「慌てて出てきた、还穿着睡衣」的场景不符。④译文：按约定时间到朋友家按门铃，他慌慌张张地出来，（一副刚起床的）样子，还穿着睡衣。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"この道路拡張計画を（ ）にあたっては、市民の皆様のご理解が必要です。", passage:"", opts:["進めた","進める","進めたい","進めよう"], ans:1, exp:"①「進めるにあたっては」＝在推进…之际，第2项正确。②考点：接续——V1/V2/V3辞書形＋にあたって（は）／N＋にあたって（重大な行動の開始時点）。③排除：1「た形」接にあたって不成立；3「～たい」是愿望形；4「意志形（おう）」也不接。④译文：在（推进）这项道路扩建计划之际，需要市民们的理解。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"A「このシャツ、かわいい。でも、会社に着ていくには派手かな。」B「うん。デートで着る（ ）、仕事には派手すぎるよ。」", passage:"", opts:["にしては","としたら","ならともかく","からとはいえ"], ans:2, exp:"①「Aならともかく、Bには～」＝A还情有可原，B就…了，第3项正确。②考点：接续——N／V辞書形＋ならともかく（列举对比项并让步前项）。③排除：1「にしては」＝就…而言太…，须同一对象自相矛盾；2「としたら」是假定，与后句判断不搭；4「からとはいえ」＝虽说，须接原因句。④译文：约会穿（还行），上班穿就太花哨了。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"上司：「ゼミナー会場の準備はどう？順調？」部下：「ええ、いすも並べ終わりましたし、（ ）資料を受付に運ぶだけです。」", passage:"", opts:["特に","あとは","少しも","あまりに"], ans:1, exp:"①「あとは資料を運ぶだけです」＝（接下来）只要搬资料就行，第2项正确。②考点：Adv「あとは」与「～るだけ」呼应，表示只剩最后一道工序。③排除：1「特に」与「だけ（只有）」矛盾；3「少しも」须接动词否定；4「あまりに」＝过于，后句须接评价或结果。④译文：椅子也摆完了，（接下来）只要把资料搬到接待处就行。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"この馬の絵は本物そっくりに描かれていて、今にも（ ）。", passage:"", opts:["走っていたい","走っているようだ","走り出しそうだ","走り出したがる"], ans:2, exp:"①「今にも走り出しそうだ」＝仿佛马上要跑起来，第3项正确。②考点：接续——V1辞書形＋そうだ（様態，眼看就要…）；「今にも」专门呼应様態。③排除：1「～たい」是愿望，画没有愿望；2「～ようだ」是对既成状态的推断，与「今にも（马上）」矛盾；4「～がる」用于第三人称意愿，不能用于画像。④译文：这匹马画得栩栩如生，（仿佛马上要跑起来）。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"最近、よくお腹が痛くなるので、病院で診てもらったら、（ ）ストレスが原因だろうと言われた。", passage:"", opts:["どうか","まさか","おそらく","いったい"], ans:2, exp:"①「おそらく＋だろう」＝大概、想必（有根据的推测），第3项正确。②考点：Adv与推测语气的呼应——おそらく～だろう／～にちがいない。③排除：1「どうか」用于请求或愿望（どうかお大事に）；2「まさか」须接否定或意外事态（まさか～ないだろう）；4「いったい」用于疑问（いったいどうして）。④译文：最近老肚子疼，去医院看了，（大概）是压力造成的吧。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"上田：「課長、すみません、今日お休みをいただけないでしょうか。娘と夫が風邪で熱を出してしまったんです。」課長：「それは大変だね。わかりました。看病で疲れて、上田さんが（ ）。」", passage:"", opts:["倒れなくなるよ","倒れてしまいたくないのに","倒れないことになるの","倒れてしまわないようにね"], ans:3, exp:"①「倒れてしまわないようにね」＝请别累倒了，第4项正确。②考点：接续——V1/V2/V3未然形＋ないように（＋ね）＝表叮嘱、提醒的祈使表达。③排除：1「倒れなくなるよ」语义相反；2「倒れてしまいたくないのに」主体变成说话人自己；3「倒れないことになるの」是自然结果的推断，不是叮嘱。④译文：照顾病人很累，（别）把你自己（累倒）了。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"わが国は、石油や石炭などのエネルギー資源がほとんどないため、多くを海外からの輸入に（ ）。", passage:"", opts:["頼らざるを得ない","頼るわけにはいかない","頼らないに違いない","頼ることにほかならない"], ans:0, exp:"①「頼らざるを得ない」＝不得不依赖，第1项正确。②考点：接续——V1未然形（頼ら）＋ざるを得ない（书面语，不得已）。③排除：2「～わけにはいかない」＝出于情理不能…，此处是客观条件所迫而非情理；3「頼らないに違いない」＝想必不依赖，与「資源がほとんどない」的因果相反；4「～にほかならない」是断定「无非是」，而前句是原因，需要表无奈必然的①。④译文：我国几乎没有石油煤炭等能源资源，（不得不）大量依赖进口。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"A「ねえ、昨日できたパンフレットってどこにある?」B「えつと、どこだろう。」C「ああ、（ ）、あの棚の中にあるよ。」", passage:"", opts:["パンフレットなら","パンフレットでも","パンフレットについて","パンフレットのことで"], ans:0, exp:"①「N＋なら」＝提到…的话（指定话题），第1项正确。②考点：助词「なら」的话题指定用法——N＋なら＝你说的那个N的话。③排除：2「でも」表举例或让步（パンフレットでも＝即使是宣传册），不合；3「について」须接说明类动词（パンフレットについて説明する），直接接「あの棚に」不通；4「ことで」须构成名词短语后接动词。④译文：啊，（宣传册的话），在那个架子里面。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 2（jlpt247整理）", q:"春子「親戚がたくさん送ってきてくれたんだけど、一人じゃ食べ切れなくて。よかったら、少し（ ）?」えり「いいの?ありがとう。」", passage:"", opts:["あげない","くれない","もらってくれない","もらってもらわない"], ans:2, exp:"①「少しもらってくれない？」＝能收下一点吗（让对方为我而收下），第3项正确。②考点：授受动词的方向——说话人是给予方，用「Vて（し）＋もらう＋てくれる」的恳请问句；答句「いいの?谢谢」正对应「收下」。③排除：1「あげない」方向虽是给对方，但否定＋疑问不通；2「くれない」＝能给我吗，方向颠倒（说话人并非索要）；4「もらってもらわない」双重授受且否定，语义混乱。④译文：亲戚寄来好多（橘子），一个人吃不完。不介意的话，（能收下一点吗）？", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"「リマインド」とは、「再確認」の意味を持ち、「会議の日程が近づいてきたので、出席者にリマインドした。」（ ）使用されるビジネス用語である。", passage:"", opts:["というように","というような","ということのように","ということのような"], ans:0, exp:"①「引用＋ように＋動詞」＝如同…那样地，「というように使用される」＝如同例句那样被使用，第1项正确。②考点：接续——引用句＋というように＋V（方式上的副词用法，修饰后面的「使用される」）。③排除：2「というような」是连体词，后面必须接名词（というような使用は…），不能直接接动词；3、4「ということの」名词化后再接也需名词，且语义冗余。④译文：「Remind」一词带有「再确认」之意，是（如例句那样使用的）商务用语。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"水泳クラブの山田コーチは、私たちにとってコーチ（ ）兄のような存在です。", passage:"", opts:["に限らず","なしには","のおかげで","というより"], ans:3, exp:"①「N＋というより＋N」＝与其说是…不如说是…，第4项正确。②考点：接续——N＋というより＋N（比较后选择后者）。③排除：1「に限らず」＝不限于，须配「だけでなく」（コーチに限らず兄…）；2「なしには」＝没有…就（不），须接否定；3「のおかげで」＝多亏，语气与「存在」的比喻不搭。④译文：山田教练对我们来说（与其说是）教练，（不如说）是哥哥般的存在。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"X社の健康食品はテレビ番組で紹介（ ）以来、とても売れている。", passage:"", opts:["されて","される","されている","された"], ans:0, exp:"①「紹介されて以来」＝自从被介绍以来，第1项正确。②考点：接续——V1/V2/V3て形＋以来（自某一时点起持续到现在）；「以来」要求前面是已发生的事件，用受身て形「されて」。③排除：2「される」是未然形，不能直接接「以来」；3「されている」是进行/持续态，无法标出起点；4「された」的た形＋以来不如定型「て形＋以来」自然，考句考查的正是「V-て以来」这一接续。④译文：X公司的健康食品自从在电视节目上被（介绍）后，一直热销。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"私たちが旅館に着くと、従業員たちが笑顔で「ようこそ（ ）」とあいさつしてくれた。", passage:"", opts:["お越しくださいました","お伺いました","お呼びいただきました","お迎えしました"], ans:0, exp:"①「ようこそお越しくださいました」＝欢迎光临（过去尊敬），第1项正确。②考点：敬语——「来る」的尊敬语「お越しになる」→丁寧表达「お越しくださいました」；「ようこそお越しくださいました」是固定欢迎语。③排除：2「お伺いました」是行く/来る的自谦（主体须是自己）；3「お呼びいただきました」＝被邀请，语义不通；4「お迎えしました」是自谦「我来迎接」，用于自己一方的行为。④译文：我们一到旅馆，工作人员就微笑着说「（欢迎光临）」。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"今はスポーツも演劇もテレビで見られる時代だが、直接見ることに（ ）得られない感動というものがある。", passage:"", opts:["とってしか","よってしか","ついてのみ","対してのみ"], ans:1, exp:"①「N＋によってしか＋可能形否定」＝唯有通过…才能，第2项正确。②考点：接续——N＋によって（手段・媒介）＋しか＋V-ない（唯一的手段）。③排除：1「にとってしか」不成立（取る→にとっては表立场）；3「ついてのみ」应为「についてのみ＝仅关于」，与「得られない」接不上；4「対してのみ」表对比（AはBに対して），不表手段。④译文：如今体育和戏剧都能在电视上看，但有些感动（只有）现场看（才能）获得。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"昨日購入した中古の大型バイクは、かなり古いものなのだが、とてもきれいな状態だった。前の持ち主によほど大切に（ ）。", passage:"", opts:["されてもおかしくない","し続けてもおかしくない","されていたに違いない","し続けていたに違いない"], ans:2, exp:"①「されていたに違いない」＝想必（过去）一直被爱惜着，第3项正确。②考点：接续——V1/V2/V3ていた＋に違いない（对过去的强烈推断）；主语是车，须用受身「（大切に）される」。③排除：1「されてもおかしくない」＝被…也不奇怪，是假设语气，与「きれいだった」这一既定事实不搭；2、4是主动态「する」，车不能自己爱护自己。④译文：昨天买的二手大排量摩托虽很旧，却状态极好。前车主想必（一直）很爱惜它。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"髪が傷んでしまうので髪を洗った後は、濡れた（ ）、しっかり乾かしましょう。", passage:"", opts:["ままにせず","ようになっても","だけにすれば","ことにならなくて"], ans:0, exp:"①「濡れたままにせず」＝别让头发湿着（放着），第1项正确。②考点：接续——V1/V2た形（濡れた）＋まま＋にせず（～ないで）；「V-たまま」＋ない形表示不保持该状态。③排除：2「ようになっても」是方式假定，与「しっかり乾かしましょう」的建议不通；3「だけにすれば」表限定原因；4「ことにならなくて」表规定、安排，与句义无关。④译文：为免伤发，洗完头（别）让头发湿着，要好好吹干。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"毎朝体操を（ ）、硬かった体が柔らかくなった。", passage:"", opts:["続けるうちに","続けるからには","続けるとすると","続けるかというと"], ans:0, exp:"①「続けるうちに」＝在坚持做的过程中，第1项正确。②考点：接续——V1/V2/V3辞書形＋うちに（期间内不知不觉发生的变化）；「硬かった体」提示持续状态。③排除：2「からには」＝既然，后句应接义务或决心（頑張らねば）；3「とすると」＝若那样，须接假定结果；4「かというと」＝若说，表反论或举例。④译文：坚持每天做体操，（在做的过程中）僵硬的身体变柔韧了。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 3（jlpt247整理）", q:"先生：「皆さん、海や川に落ちてしまったときは、無理に（ ）、仰向になって、浮かんで助けを待つことが大切です。」", passage:"", opts:["泳げなくなると","泳ごうとしないので","泳げなくなって","泳ごうとしないで"], ans:3, exp:"①「泳ごうとしないで」＝不要勉强试图游泳，第4项正确。②考点：接续——V1意志形（泳ごう）＋とする＋ない形（しないで）＝别试图做…。③排除：1「泳げなくなると」是可能形的变化，接续与语义都不通；2「～ないので」表原因，后句应接结果而非建议；3「泳げなくなって」是状态变化，与「無理に」搭配不成立。④译文：掉进海里时，不要勉强（挣扎游水），仰面浮起等待救援很重要。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"卓球クラブの山谷さんは大きな大会で何度も優勝しているのに「私（ ）まだまだですよ」といつも言っている。", passage:"", opts:["まで","さえ","ばかり","なんか"], ans:3, exp:"①「私なんか」＝我这种人（自谦、随意的说法），第4项正确。②考点：接尾词「N＋なんか」用于自谦或随意列举（私なんか・こんなものなんか）。③排除：1「まで」表程度上限或连…也（私まで）；2「さえ」表极端举例（私さえ）；3「ばかり」＝只、光，须与他人对比（私ばかり），此处不成立。④译文：山谷明明多次夺得大赛冠军，却总说「（我这种人）还差得远呢」。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"花山市では、きゅうりやトマト、なす（ ）夏の野菜が多く生産されている。", passage:"", opts:["とする","に関する","といった","にそった"], ans:2, exp:"①「N＋といった＋N」＝…之类的（例示），第3项正确。②考点：接续——N（具体例）＋といった＋N（书面语的例示用法）。③排除：1「とする」须构成「AをBとする」的框式结构，不能连接两个名词表举例；2「に関する」＝关于（きゅうりに関する資料），接续方向相反；4「にそった」＝沿着（方針にそって），语义不通。④译文：花山市大量生产黄瓜、番茄、茄子（等）夏季蔬菜。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"家の近所に子供向けのダンススクールができるらしい。オープンしたら、娘を体験レッスンに（ ）と話している。", passage:"", opts:["参加してみようか","参加させてみようか","参加してみてよかった","参加させてみてよかった"], ans:1, exp:"①「参加させてみようか」＝让（女儿）试着参加一下吧，第2项正确。②考点：接续——V1/V2/V3未然形（参加させ）＋てみる＋意志形（うと思う）；对象是孩子，故用使役态表达「让某人做」。③排除：1「参加してみよう」的主体会变成说话人自己，与「娘を」矛盾；3、4「～てよかった」是对已发生之事的评价，与「オープンしたら（将来）」的语境冲突。④译文：我家附近要开儿童舞蹈班，（打算让）女儿（去）体验一下。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"母：「引っ越しまでまだ時間はあるけど、直前になってあわてないように（ ）。荷物の整理も進めておきなさい。」息子：「うん、分かった。」", passage:"", opts:["しだけでいいのに","少しだけならよくでも","少しずつやっておこう","少しずつならよくて"], ans:2, exp:"①「少しずつやっておこう」＝（先）一点点预先做起来吧，第3项正确。②考点：接续——V1/V2/V3て形＋ておく（预先准备）＋意志形表提议；与后句「進めておきなさい」呼应。③排除：1句首缺「少しずつ」等成分，「しだけでいいのに」不通；2「少しだけならよくでも」接续错误；4「少しずつならよくて」接续错误，且与「あわてないように」的目的不符。④译文：离搬家还有时间，（一点点先）收拾起来吧，免得到时手忙脚乱。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"1896年に第1回オリンピックに参加した国と地域の数は14だったが、2004年には200を超える（ ）。", passage:"", opts:["べきだった","つもりだった","ほかなかった","までになった"], ans:3, exp:"①「200を超えるまでになった」＝（数量）达到了超过200的程度，第4项正确。②考点：接续——数量N＋に（まで）なる＝变化达到某规模（大幅增长的表达）。③排除：1「べきだった」＝本应该（却没做），此处是客观增长；2「つもりだった」＝打算，与事实陈述不符；3「ほかなかった」＝只好，语境中没有「不得已」的语义。④译文：1896年首届奥运会有14个国家和地区参加，到2004年（已达）200多个。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"チームでの仕事をスムーズに進めるには、メンバー同士の十分なコミュニケーション（ ）。", passage:"", opts:["にすぎない","が欠かせない","のおかげだ","とのことだ"], ans:1, exp:"①「N＋が欠かせない」＝…是必不可少的，第2项正确。②考点：接续——N＋が欠かせない（～がなければできない，强调必要性）。③排除：1「にすぎない」＝只不过是，与「進めるには（目的）」矛盾；3「のおかげだ」＝多亏，因果方向不符；4「とのことだ」是传闻转述，「コミュニケーションとのことだ」句义不通。④译文：要顺利推进团队工作，成员之间充分的沟通（不可或缺）。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"昨日、遊園地に行った。電車より車のほうが早いだろうと思って車で行ったら、ひどい渋滞でかえって時間がかかってしまった。やはり電車で（ ）。", passage:"", opts:["行けばよかった","行くはずだった","行かなくて済んだ","行きたくてしかたがなかった"], ans:0, exp:"①「行けばよかった」＝当初（坐电车去）就好了（后悔），第1项正确。②考点：接续——V1/V2/V3辞書形（行けば＝V1ば形）＋よかった＝对过去未做之事的后悔。③排除：2「行くはずだった」＝本该去，须接「のに」表遗憾；3「行かなくて済んだ」＝没去成，与后悔相反；4「行きたくてしかたがなかった」＝非常想去，时态和事实都不符。④译文：还是（坐电车去就好了）。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"駅前に新しくできたカフェに友達を誘って行ってみたら、定休日だった。事前に確認しておく（ ）。", passage:"", opts:["しかなかった","ほどではなかった","べきだった","せいだった"], ans:2, exp:"①「確認しておくべきだった」＝本应该事先确认的（反省），第3项正确。②考点：接续——V1/V2/V3辞書形＋べきだ＋た形＝本该做却没做的反省语气。③排除：1「しかなかった」＝只有，不通；2「ほどではなかった」＝没到…程度，前面须接评价性内容；4「せいだった」＝都怪，后句须接不良结果的归因。④译文：带朋友去站前新开的咖啡馆，结果定休。（本应该）事先确认一下的。", t:""},
  {type:"gram", src:"N2真题·2024年7月（jlpt247整理）", q:"A「お電話ありがとうございます。ABC建設営業課でございます」B「高橋さんはいらっしゃいますか。」A「失礼ですが、お名前を（ ）。」", passage:"", opts:["伺ったらいかがでしょうか","伺ってもよろしいでしょうか","お伝えしたらいかがでしょうか","お伝えしてもよろしいでしょうか"], ans:1, exp:"①「お名前を伺ってもよろしいでしょうか」＝可以请教您的姓名吗（郑重的许可问句），第2项正确。②考点：接续——（お＋）N＋を＋V1/V2/V3て形＋もよろしいでしょうか（许可的郑重说法），且「伺う」是「聞く・行く」的谦让语，用于询问对方姓名。③排除：1「伺ったら」是假定「如果我问了的话」，语义不通；3「お伝えしたら」＝（我）转告的话，方向相反（是要问对方）；4「お伝えしても」＝（我）告知也可以吗，语义不通。④译文：不好意思，（可以）请教（您）的姓名吗？", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"60代の父が、趣味（ ）何歳から始めても遅くないだろうと言って、最近ピアノ教室に通い始めた。", passage:"", opts:["としてだけ","としてなら","にとっては","にとっても"], ans:1, exp:"①「趣味としてなら」＝若作为爱好的话，第2项正确。②考点：接续——N＋としてなら（＝Nとしてはという限定视角下的让步判断）。③排除：1「としてだけ」须接否定或强烈限定（趣味としてだけなら…）；3「にとっては」＝对…而言（评价基准），后句须接价值判断；4「にとっても」同上，与「何歳から始めても」的可行性判断不搭。④译文：60岁的父亲说，（作为爱好）无论多大开始都不算晚，最近开始学钢琴了。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"A「田中さんに話があるんだけど、今、会議中?」B「うん。」A「じゃあ、会議が終わるのを待つ（ ）ないね。」", passage:"", opts:["しか","だけ","まで","さえ"], ans:0, exp:"①「待つしかないね」＝只好等了，第1项正确。②考点：接续——V1辞書形＋しかない＝别无他法、只好（唯一选择）。③排除：2「だけない」不成立（「だけ」须配「～だけある／～するだけだ」）；3「までない」不通（まで是格助词须接名词或表范围）；4「さえ」须构成「待つさえ（ない）」，语序与接续都不对。④译文：那（只好）等会开完了。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"彼女があのとき何を考えていたのか知りたいけれど、今はもう会うこともないので、（ ）。", passage:"", opts:["確かめかねない","確かめるほかない","確かめようがない","確かめるわけではない"], ans:2, exp:"①「確かめようがない」＝无从确认，第3项正确。②考点：接续——V1辞書形＋ようがない（～する方法・余地がない，无从…）。③排除：1「確かめかねない」＝难以（开口）确认，须指对对方不好开口的场合；2形式错误（正确应为「確かめるしかない／ほかない」）；4「わけではない」＝并不是要确认，与「知りたい」矛盾。④译文：虽然想知道她当时在想什么，但如今再也见不到了，（无从确认）。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"12年間付き合っている彼女に、今年（ ）結婚を申し込もうと思っている。", passage:"", opts:["こそ","さえ","すら","のみ"], ans:0, exp:"①「今年こそ」＝就是今年（表强烈决心的强调），第1项正确。②考点：提示助词「N＋こそ」——强调限定并引出后项的决心（今年こそ成功させたい）。③排除：2「さえ」表极端举例（…さえ）；3「すら」＝甚至，多接消极内容；4「のみ」＝只、仅（书面），不表强调决心。④译文：和交往12年的女友，（就）今年（要）求婚。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"今日は、本当は映画を（ ）が、雪が降ってきたので、やめた。", passage:"", opts:["見に行ってばかりだ","見に行ったばかりだ","見に行くつもりだった","見に行ったつもりだった"], ans:2, exp:"①「見に行くつもりだった」＝原本打算去看电影，第3项正确。②考点：接续——V1辞書形＋つもりだ＋た形＝过去的打算（并未实现）。③排除：1「～てばかりだ」须接て形且表「刚做完」，接续与时态都不合；2「～たばかりだ」＝刚去过，与「やめた」矛盾；4「～たつもりだ」＝自以为去了，与没去成的事实冲突。④译文：本来（打算）去看电影的，但下起雪来就作罢了。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"私は、急な雨（ ）、いつも折り畳み傘を持ち歩いている。", passage:"", opts:["に反して","に加えて","に備えて","に応じて"], ans:2, exp:"①「急な雨に備えて」＝为防备突如其来的雨，第3项正确。②考点：接续——N＋に備える（V1）て形で＝预先为…做准备。③排除：1「に反して」＝与…相反（期待に反して）；2「に加えて」＝加之（在…之上追加）；4「に応じて」＝根据（要求に応じて），均不通。④译文：为（防备）突如其来的雨，我出门总带着折叠伞。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"私たちが住んでいる地球は、（ ）どうやってできたのでしょうか。地球誕生の秘密を見てみましょう。", passage:"", opts:["とうとう","おそらく","まもなく","いったい"], ans:3, exp:"①「いったいどうやって」＝到底是怎样（构成疑问句的强调），第4项正确。②考点：Adv「いったい」与疑问词呼应（いったい何・どうして・どういうことだ）。③排除：1「とうとう」＝终于，须接实现的动作；2「おそらく」表推测，不能修饰疑问；3「まもなく」＝马上、不久，与疑问无关。④译文：我们居住的地球（到底是）怎样形成的呢？一起来看看地球诞生的秘密吧。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"ABC大学の法学部には、六つのゼミがあります。ゼミでの活動（ ）、物事を論理的に考える力を身につけることができます。", passage:"", opts:["とは","にも","にとって","を通して"], ans:3, exp:"①「N＋を通して」＝通过…（以…为媒介/机会），第4项正确。②考点：接续——N＋を通して（手段・経路・機会を経て）。③排除：1「とは」＝所谓，须接定义内容（ゼミとは…）；2「にも」表追加或比例（活動にも役立つ），与「身につける」的手段义不搭；3「にとって」＝对…而言（立場），接续与语义都不通。④译文：通过（以）研讨班活动（为媒介），能培养逻辑思考能力。", t:""},
  {type:"gram", src:"N2真题精选·JLPT Pro 6（jlpt247整理）", q:"先生：「田中さん、この問題をどうやって（ ）、みんなの前で説明してください。」田中：「はい、わかりました。」", passage:"", opts:["解いたか","解いたのを","解いたとは","解いたことも"], ans:0, exp:"①「どうやって解いたか」＝（是）怎么解的（间接疑问），作「説明する」的内容，第1项正确。②考点：接续——疑问词＋V1/V2/V3た形＋か（＋と）＝间接疑问句作宾语。③排除：2「解いたの」只是名词化的「解题这件事」，疑问义消失；3「解いたとは」须接「言う・思う」等传闻断定（解いたとは言っていない）；4「解いたことも」须接「覚えている」等（解いたことも忘れた）。④译文：田中，请在大家面前说明这道题（是怎么解的）。", t:""},

  // ==================== 読解：排序 / 短篇 / 情報検索（read）====================
  {type:"read", src:"N2真题精选·JLPT Pro 1（jlpt247整理）·問題8排序", q:"私は、美術館では音声ガイドの機械を借りて、説明を聞きながら作品を鑑賞する。作品のどこに＿＿ ＿＿ ★ ＿＿その作品をより深く味わえるからだ。★に入る最もよいものはどれか。", passage:"", opts:["わかると","注目して","いいのかが","鑑賞したら"], ans:0, exp:"①正确语序：作品のどこに【注目して】【いいのかが】【わかると★】【鑑賞したら】その作品をより深く味わえるからだ。★处为「わかると」，即第1项。②考点：疑问短语「どこに注目していいのかが」（该注意哪里）＋V1/V2辞書形＋と的条件接续＋「鑑賞したら」表假设尝试。③排除：「注目して」必须与「いいのかが」连成「注目していいのか」置于前段，「鑑賞したら」只能放在最后引出结果，都不能进入★。④译文：我在美术馆会借语音导览，边听说明边欣赏作品。因为（明白）该注意作品的哪里，欣赏时才能体会得更深。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 1（jlpt247整理）·問題8排序", q:"「10倍がゆ」とは、＿＿ ＿＿ ★ ＿＿ おかゆのことです。★に入る最もよいものはどれか。", passage:"", opts:["作った","水で","10倍の","米1に対して"], ans:1, exp:"①正确语序：「10倍がゆ」とは、【米1に対して】【10倍の】【水で★】【作った】おかゆのことです。★处为「水で」，即第2项。②考点：「N＋に対して」的比例对应用法＋「10倍の＋N」的连体修饰＋「Vて形＋N」（水で作った＝用米做的）。③排除：「米1に対して」是比例起点须在句首，「10倍の」须紧跟「水」之前，「作った」须直接修饰「おかゆ」在最后，都不能进入★。④译文：所谓「十倍粥」，就是米与水按1比10（用十倍的水）煮成的粥。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 1（jlpt247整理）·問題8排序", q:"私は、新しいことにチャレンジするときでも悩まない。＿＿ ＿＿ ★ ＿＿ と思っているからだ。★に入る最もよいものはどれか。", passage:"", opts:["まずやってみて","もう一度考えればいい","うまくいかなかったら","そのときにどうしたらいいか"], ans:3, exp:"①正确语序：【まずやってみて】【うまくいかなかったら】【そのときにどうしたらいいか★】【もう一度考えればいい】と思っているからだ。★处为「そのときにどうしたらいいか」，即第4项。②考点：「Vて形＋みる」（先试试）＋「～たら」假定＋疑问词「どうしたらいいか」作「もう一度考える」的间接疑问内容。③排除：「まずやってみて」是起始动作置首，「うまくいかなかったら」是其后的假定，「もう一度考えればいい」是最终判断置尾，都不能进入★。④译文：我即使挑战新事物也不纠结。因为我相信：先试着做，万一不顺利，（到时候该怎么做）再重新考虑就行。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 1（jlpt247整理）·問題8排序", q:"おなかがすいている ＿＿ ＿＿ ★ ＿＿ だろう。★に入る最もよいものはどれか。", passage:"", opts:["どうして","おなかが鳴るのは","でもないのに","わけ"], ans:1, exp:"①正确语序：おなかがすいている【わけ】【でもないのに】、【おなかが鳴るのは★】【どうして】だろう。★处为「おなかが鳴るのは」，即第2项。②考点：「～わけでもないのに」（虽然并不是…也）的让步表达＋「N＋は」提示主题＋疑问词收尾的自问。③排除：「わけ」须与「でもないのに」连成固定让步置前，「どうして」只能放在句尾构成疑问，都不能进入★。④译文：明明（并不是）肚子饿，（肚子叫）到底是怎么回事呢？", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題8排序", q:"昨日は「母の日」だったので、いつもおいしいお弁当を＿＿ ＿＿ ★ ＿＿ 母が欲しがっていたアクセサリーをプレゼントした。★に入る最もよいものはどれか。", passage:"", opts:["感謝の","作ってくれて","ありがとうという","気持ちを込めて"], ans:0, exp:"①正确语序：いつもおいしいお弁当を【作ってくれて】【ありがとうという】【感謝の★】【気持ちを込めて】母が欲しがっていたアクセサリーをプレゼントした。★处为「感謝の」，即第1项。②考点：「Vて形＋ありがとうという＋N」的连体修饰链——「ありがとうという感謝の気持ちを込めて」。③排除：「作てくれて」以て形承接前句置首，「ありがとうという」必须修饰「感謝の」，「気持ちを込めて」须在最后修饰「プレゼントした」，都不能进入★。④译文：因为昨天是母亲节，我送了妈妈一直想要的饰品，（怀着）谢谢她平时做美味便当的（感谢）心意。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題8排序", q:"話題のカレー屋さんを初訪問。野菜の ＿＿ ＿＿ ★ ＿＿ 「夏限定ベジタブルカレー」。評判どおりのおいしさだった。★に入る最もよいものはどれか。", passage:"", opts:["中で","私が選んだのは","夏の野菜がたっぷり入った","カレーがいくつかある"], ans:1, exp:"①正确语序：野菜の【カレーがいくつかある】【中で】【私が選んだのは★】【夏の野菜がたっぷり入った】「夏限定ベジタブルカレー」。★处为「私が選んだのは」，即第2项。②考点：「N＋の中で」列举范围＋「選んだのは～」强调选定项＋连体修饰「たっぷり入ったカレー」。③排除：「カレーがいくつかある」须与「野菜の」衔接置首，「中で」紧随其后，「夏の野菜がたっぷり入った」只能直接修饰品名置尾，都不能进入★。④译文：第一次去话题咖喱店。在几个蔬菜咖喱中，我（选的是）放满夏日蔬菜的「夏限定蔬菜咖喱」，果然名不虚传。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題8排序", q:"＿＿ ＿＿ ★ ＿＿ 先週から工事で休業中なので、今回は別のホテルに泊まることにした。★に入る最もよいものはどれか。", passage:"", opts:["泊まっている","たびに","Yホテルが","出張に行く"], ans:3, exp:"①正确语序：【出張に行く】【たびに】【Yホテルが★】【泊まっている】先週から工事で休業中なので、今回は別のホテルに泊まることにした。★处为「Yホテルが」，即第3项。②考点：「V1辞書形＋たびに」（每次…）＋名词作连体修饰的主语「Nが＋V」（泊まっているYホテル）。③排除：「出張に行く」是「たびに」的前项须置首，「たびに」紧跟其后，「泊まっている」须直接修饰酒店名，都不能进入★。④译文：（每次）出差（住的那家）Y酒店上周起因施工停业，所以这次决定住别的酒店。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題8排序", q:"家の近くの本屋では ＿＿ ＿＿ ★ ＿＿ 少し遠いけど行ってみようと思う。★に入る最もよいものはどれか。", passage:"", opts:["買えなかった漫画の最新号が","まだ買えるらしいので","もう売り切れていて","隣町のABC書店に行けば"], ans:0, exp:"①正确语序：【隣町のABC書店に行けば】【もう売り切れていて】【買えなかった漫画の最新号が★】【まだ買えるらしいので】少し遠いけど行ってみようと思う。★处为「買えなかった漫画の最新号が」，即第1项。②考点：「V1/V2辞書形＋ば」假定＋「～ていて」状态持续＋「N＋が＋V可能形＋ので」表理由的因果链。③排除：「隣町のABC書店に行けば」是条件句须置首，「もう売り切れていて」是前句状态，「まだ買えるらしいので」须在最后给出理由，都不能进入★。④译文：听说（附近书店）没买到的那本漫画最新号，（邻镇ABC书店）还有卖，虽然远点，想去一趟看看。", t:""},
  {type:"read", src:"N2真题·2024年7月（jlpt247整理）·問題8排序", q:"同じ高温 ＿＿ ＿＿ ★ ＿＿ は大きく変わる。★に入る最もよいものはどれか。", passage:"", opts:["感じ方","でも","温度や風の強さなど","によって"], ans:3, exp:"①正确语序：同じ高温【でも】【温度や風の強さなど】【によって★】【感じ方】は大きく変わる。★处为「によって」，即第4项。②考点：「N＋でも」（即使）＋「N＋など」列举＋「N＋によって」（因…而异）＋「Nは」提示主语。③排除：「でも」须紧跟前项名词，「温度や風の強さなど」是「によって」的前项，「感じ方」只能作句尾主语，都不能进入★。④译文：即使是同样的高温，（也会因）温度、风力等（而不同），（给人的）感觉（方式）差别很大。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 6（jlpt247整理）·問題8排序", q:"昨日、初めてパンを作ってみた。料理雑誌の ＿＿ ＿＿ ★ ＿＿ 、うまく膨らまなかった。★に入る最もよいものはどれか。", passage:"", opts:["のに","レシピに書いてある","とおりに","作った"], ans:3, exp:"①正确语序：料理雑誌の【レシピに書いてある】【とおりに】【作った★】【のに】、うまく膨らまなかった。★处为「作った」，即第4项。②考点：「N＋に書いてある＋とおりに」（按照…写的做法）＋「Vた形＋のに」（…却）表反预期的转折。③排除：「レシピに書いてある」须先修饰做法内容置首，「とおりに」紧随其后，「のに」只能放在最后表转折，都不能进入★。④译文：昨天第一次试着做面包。明明（照着）食谱上写的（做了），却没发起来。", t:""},

  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題10短篇", q:"インタビューについて、筆者の考えに合うのはどれか。", passage:"インタビューでは準備も重要だが、実際のインタビューの場面になったら、いったんその準備で得たものをすべて捨てなくてはならない。そして、相手の話を真剣に深く聞き、その人が何を言わんとしているのか、丸ごと捉えて、そこで出てきた素晴らしい言葉、豊かな言葉、言葉に込められた大事なメッセージをしっかりとつかむことこそが必要なのだ。そこから良い対話が生まれてくる。良いインタビューは、次の質問を忘れて相手の話を聞けたときに初めて行えるものなのだ。（注1）言わんとしている：言おうとしている （注2）丸ごと：そのまま全部", opts:["準備したものから離れて、相手の話をよく聞くことが重要だ。","準備した質問に沿って、相手から大事なメッセージを引き出すことが重要だ。","相手の話をしっかり聞くことが大切なので、準備をする必要はない。","相手から素晴らしい言葉を引き出すには、準備しすぎないほうがいい。"], ans:0, exp:"①第1项正确：原文「準備で得たものをすべて捨てなくてはならない」「次の質問を忘れて相手の話を聞けたときに初めて行える」＝要抛开既定准备、全心倾听。②考点：短篇主张题——锁定「～ことこそが必要だ」「初めて」这类结论标记。③排除：2「沿って準備した質問に沿って」与「すべて捨てなくてはならない」相反；3说不需要准备，而开头明确「準備も重要」；4「準備しすぎない」文中未涉及。④全文译文：采访中准备固然重要，但真正进入采访时，必须先把靠准备得来的东西全部放下。然后认真深入地倾听对方，整体把握他想表达什么，抓住那些精彩、丰富的语言和其中的重要信息，由此才会产生好的对话。好的采访，只有在忘记下一个问题、专心听对方说话时才算真正成立。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題10情報検索", q:"「緑山牧場チーズ詰め合わせ」を社内販売で購入したい社員は、期日までに営業課にメールで申し込んだあと、どうすればいいか。", passage:"【社員各位】わが社の人気商品「緑山牧場チーズ詰め合わせ」を、定価の30%引き（割引後3,500円）で社員向けに特別販売します。購入希望者は、添付の申込書にお名前と購入数をご記入のうえ、3月9日までに営業課までメールでお申し込みください。通常、社内販売の支払いと商品のお渡しは経理課で行っていますが、今回は営業課で行います。代金と引き換えに、その場で商品をお渡しします。お渡し期間は3月16日から19日の間です。以上、よろしくお願いします。 （3月1日 「緑山牧場チーズ詰め合わせ」申込書 営業課 安井）", opts:["経理課で支払いをして受け取る。","経理課で支払いをして、営業課で受け取る。","営業課で支払いをして受け取る。","営業課で支払いをして、経理課で受け取る。"], ans:2, exp:"①第3项正确：文中「今回は営業課で行います。代金と引き換えに、その場で商品をお渡しします」＝这次付款与领货都在营业课当面完成。②考点：信息检索——注意「通常は経理課」与「今回は営業課」的例外提示，「代金と引き換え」说明钱货同时同地。③排除：1、2沿用通常流程，与「今回は」矛盾；4把付款与领货拆到两个部门，与「その場で」不符。④译文：见上文——本次特别贩售的付款与领货均在营业课进行，申领后到营业课付款并当场取货。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題10短篇", q:"鳥の記憶について、筆者の説明に合うのはどれか。", passage:"鳥は日常的に目であたりを観察し、自身の生活にとって重要なものかどうかを見分け、必要なものを優先的に記憶しながら暮らしています。野生と飼育下では、そこに存在するものがちがっているため、重要と判断されるものも大きく変わってきますが、判断のしかた自体は変化しません。重要なものは詳細に、そうでないものはさっと流すくらいの注意で見る、というやりかたです。そして、重要と判断されなかったものは、どんどん記憶のなかから消えていきます。（注1）野生：自然のなかで生きている状態 （注2）飼育下：飼われている状態", opts:["何度も見たものを重要だと判断して記憶していく。","生活する場がちがっても、同じものを記憶していく。","生活に重要なものを選んで記憶していく。","生活に重要なものでも、次第に記憶から消えていく。"], ans:2, exp:"①第3项正确：「自身の生活にとって重要なものかどうかを見分け、必要なものを優先的に記憶」＝挑选对生活重要的信息去记。②考点：短篇内容一致——注意「重要と判断されなかったものは…消えていく」的补充句。③排除：1判断依据是「重要与否」，不是「看的次数」；2原文说野生与饲养环境下「重要と判断されるもの」大不相同；4被判断为重要的会优先记住，被淘汰的是不重要的。④全文译文：鸟平常用眼观察周围，分辨对自身生活是否重要，优先记住必要的东西。野生与饲养环境下存在的事物不同，被判定为重要的内容也大不相同，但判断方式本身不变：重要的细看，不重要的扫一眼带过；未被判断为重要的，会逐渐从记忆中消失。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題10短篇", q:"この文書で最も伝えたいことは何か。", passage:"【10月5日 住民の皆様へ ごみに関するお願い】最近、「可燃ごみ」の回収日に衣類・布類が多く出されています。しかし、市の規則では、衣類・布類は毎週火曜日の「資源ごみ」の回収日に出すことになっています。資源を有効に活用するため、決められた回収日に出してください。衣類・布類は、市内8か所の公共施設に設置してある回収ボックスでも回収しています。回収後は、中古の衣類として再使用したり、工場で再生利用したりします。ご協力をよろしくお願いします。（竹川市役所 市民生活課）", opts:["「資源ごみ」として出す衣類・布類の量を減らしてほしい。","「資源ごみ」の回収日に「可燃ごみ」を出さないでほしい。","衣類・布類は、「資源ごみ」の回収日に出してほしい。","衣類・布類は、新しく設置した回収ボックスに出してほしい。"], ans:2, exp:"①第3项正确：核心规则句是「衣類・布類は…資源ごみの回収日に出すことになっている」「決められた回収日に出してください」。②考点：通知类文書——首段摆问题、中段给规则、结尾提请求，答案取规则句。③排除：1不是要减少数量；2因果颠倒（要纠正的是把衣类当可燃垃圾扔）；4回収ボックス是「另外也可以」的补充，且并非「新設」。④全文译文：见上文——请把衣类、布类按市规定在每周二「资源垃圾」回收日丢弃（也可投到市内8处公共设施的回收箱），以便资源再利用。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題10短篇", q:"筆者は、ひとと出会うことによってどうなると述べているか。", passage:"自分が常識と思っていたこと、そうして見えない枠として自分をしばっていたこと、それを共有しないひとが現われる。最初、それは非常識なひと、変なひとに思えるかもしれない。だけど、それが変だと感じることで、はじめて、自分があたりまえだと思っていたことを自覚するようになる。見えない枠が見えるようになる。（注）自覚する：意識する", opts:["見えない枠が変なものだと気づく。","自分をしばっていた考え方に気づく。","自分の常識が間違いだったと気づく。","ほかのひとの常識は理解できないと気づく。"], ans:1, exp:"①第2项正确：「それが変だと感じることで、はじめて、自分があたりまえだと思っていたことを自覚するようになる。見えない枠が見えるようになる」＝遇见与自己不同的人，才意识到束缚自己的无形框架。②考点：主张一致——末句「見えない枠が見えるようになる」是换言结论。③排除：1不是觉得「枠」本身奇怪，而是发现自己的枠；3原文没说自己的常识「错了」；4话题焦点是自己的框架，不是理解不了对方。④全文译文：当你遇到一个与你所认定的常识不共享的人时，起初会觉得对方不可理喻、奇怪；但正因为感到「奇怪」，你才第一次意识到自己一直当作理所当然的东西——那道束缚自己的、看不见的框变得可见了。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題10短篇", q:"不快な感情について、筆者の考えに合うのはどれか。", passage:"恐い、恥ずかしい、淋しい、腹が立つなどは、不快な感情ではありますが、単に取り除かれればよいもの、存在しなければよいものではありません。それらが一切存在しない理想の人生があると考えるのは間違いで、それらには存在する理由があるのです。どんなにまれな人生でも、恐いことはありますし、恥ずかしいこと、淋しいこと、腹が立つことはあります。むしろそういう感情があることが豊かな人生だとさえ言えます。（注1）腹が立つ：怒りを感じる （注2）一切：全く", opts:["不快な感情を持てば持つほど、人生はより豊かになる。","不快な感情を取り除ければ、理想の人生が送れる。","不快な感情が存在する理由を考えることで、人生は豊かになる。","不快な感情があるからこそ、人生は豊かになる。"], ans:3, exp:"①第4项正确：「むしろそういう感情があることが豊かな人生だとさえ言えます」＝正因有这些不快情绪，人生才谈得上丰富。②考点：主张一致——抓「むしろ～だとさえ言えます」的强断定句。③排除：1原文没有「越多越好」的比较；2与「取り除けばよいものではない」直接相反；3重点不是思考存在理由，而是「存在本身」的价值。④全文译文：害怕、害羞、寂寞、生气等虽是不快情绪，却不是只要消除或不存在就好的东西。认为存在完全没有它们的理想人生是错的——它们的存在自有理由；即使再顺遂的人生也难免这些情绪。不如说，正因有这些感情，人生才称得上丰富。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題10情報検索", q:"「花」シリーズを買いたい場合、どうすればいいか。", passage:"【オリジナル帽子店「マリー」期間限定・特別ショップのお知らせ】このたび、4月1日から15日までの期間限定で、南野デパートに特別ショップを開店いたします。特別ショップでは、通常の商品に加え、春の新商品を販売いたします。春の新商品のうち、「花」シリーズは、特別ショップのみでの販売となりますので、ぜひこの機会にご来店ください。", opts:["4月1日から15日までの間に特別ショップに行く。","4月1日から15日までの間に特別ショップか「マリー」各店に行く。","4月1日から15日までの間は特別ショップに行き、16日以降は「マリー」各店に行く。","4月16日以降に特別ショップか「マリー」各店に行く。"], ans:0, exp:"①第1项正确：「花」系列「特別ショップのみでの販売」＋期间为4月1日至15日，故只能在此期间去南野百货的限定店。②考点：信息检索——「のみ」排除总店，日期条件排除16日以后。③排除：2、3都含「マリー各店」，违反「仅限特别店」；3还弄错日期；4日期与地点双双不符。④全文译文：见上文——「花」系列只在4月1日至15日南野百货的期间限定特别店有售，须在此期间前往该店购买。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題10短篇", q:"本文の内容に合うのはどれか。", passage:"「適度に暖かく、発芽に使える水があり、呼吸もできるという条件がそろえば、多くの植物のタネは発芽する」と思われがちです。しかし、実際には、そうではありません。多くの植物のタネは、発芽の三条件がそろったからといって、うかつに発芽しないのです。なぜなら、発芽の三条件の中には、「光が当たること」という条件が入っていないからです。もし、光の当たらない場所でタネが発芽すれば、発芽した芽生えがどんな運命をたどるかは、容易に想像がつきます。（注1）発芽：芽を出すこと （注2）うかつに：ここでは、簡単に （注3）芽生え：ここでは、芽 （注4）どんな運命をたどるか：ここでは、どうなっていくか", opts:["発芽の三条件がそろった状態で光が当たっても、育たないことがある。","発芽の三条件がそろって発芽しても、光が当たらなければ成長しにくい。","発芽の三条件は、光が当たることよりも重要だ。","発芽の三条件は、光の当たらない場所ではそろいにくい。"], ans:1, exp:"①第2项正确：三条件齐备也不会轻易发芽，因为其中没有「照到光」；若在无光处勉强发芽，芽的命运可想而知＝缺光则难健康成长。②考点：内容一致——注意「しかし」的转折与「なぜなら」的理由句。③排除：1「光が当たっても育たない」与文意相反（光是需要的）；3文中没有三条件与光的重要性比较；4没说三条件在暗处「难以齐备」。④全文译文：人们常以为只要温暖、有水、能呼吸三条件齐备种子就会发芽，其实不然——即使三条件齐备也不会轻易发芽，因为其中并不包括「照到光」。若在无光处发芽，芽的命运不难想象（难以健康成长）。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題10情報検索", q:"このメールで問い合わせていることは何か。", passage:"【件名：「何でもハサミ」のミラ商会への納品について／4月30日 11:55／商品管理課安村様】お疲れさまです。6月15日発売の「何でもハサミ」の件ですが、ミラ商会の担当者から連絡がありました。価格についての問題は解決しましたが、納品数については、最初の予定の50本ではなく、80本に変更してほしいとのことです。今週中に返答しなければならないのですが、今から30本増やすことは可能でしょうか。納品日は5月20日で、変更ありません。ご検討よろしくお願いします。（営業課 大森）", opts:["ミラ商会に、最初の予定より早く納品できるか。","ミラ商会の希望する価格で、納品できるか。","5月20日に、ミラ商会に80本を納品できるか。","今週中に、ミラ商会に30本を納品できるか。"], ans:2, exp:"①第3项正确：邮件核心问句是「今から30本増やすことは可能でしょうか」，前提是交付日仍为5月20日、数量由50本改为80本。②考点：邮件检索——分清「已解决（价格）」「变更请求（数量）」「不变项（交期5月20日）」。③排除：1交期明确「変更ありません」，不是提前交货；2价格问题已解决，非询问点；4「今週中」是答复期限，不是交付时间。④全文译文：见上文——对方要求把原定50本改为80本，故本邮件询问能否在5月20日交付80本。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題10短篇", q:"問題解決について、筆者の考えに合うのはどれか。", passage:"仕事でも、人生でも、大切なことは、自分に降り掛かる問題をいかに解決していくか、という作業の繰り返しである。ある人は問題から逃げる。これも、その人にとっての解決である。しかし、そういう人は逃げ続けなければならない。一度きちんと解決をした人は、同じ問題に遭遇したときに対処できる。このようにしてスキルが上がっていき、その後得をするだろう。（注1）降り掛かる：ここでは、自分に起きる （注2）いかに：どうやって （注3）スキル：能力や技術", opts:["問題に取り組む経験を積むほど、問題に対処できるようになる。","問題から逃げることも、問題の解決には必要である。","人生で得をするために、複雑な問題に積極的に取り組むべきだ。","解決できたかどうかより、問題解決に取り組む態度が大切だ。"], ans:0, exp:"①第1项正确：「一度きちんと解決をした人は、同じ問題に遭遇したときに対処できる。このようにしてスキルが上がっていき、その後得をする」＝解决经验积累使应对能力提升。②考点：主张一致——末段因果链即作者主张。③排除：2原文说逃避者「必须一直逃下去」，并非肯定其为必要手段；3「为获益而主动挑战复杂问题」文中未提；4作者强调的是真正解决带来的技能增长，而非态度本身。④全文译文：无论工作还是人生，关键都是如何解决降临到自己身上的问题，如此反复。有人逃避——那对他也算一种解决，但从此只能一直逃。认真解决过一次的人，再遇同类问题便能应对，技能随之提升，之后自然受益。", t:""},
  {type:"read", src:"N2真题·2024年7月（jlpt247整理）·問題10情報検索", q:"このお知らせで伝えたいことは何か。", passage:"【トップ＞お知らせ＞定期システム点検実施のお知らせ】当社では情報管理システムの安全性向上のため、第4土曜日の夜間にシステム点検を実施しております。今月の作業は6月23日(土) 午前2時から4時までとなります。この間は、予約システムを休止いたします。インターネットでの特急券予約がご利用いただけなくなりますのでご注意ください。なお、ホームページ内の時刻表や運賃表は通常どおり閲覧が可能です。ご不便をおかけいたしますが、ご理解くださいますようお願い申し上げます。（北坂鉄道株式会社）", opts:["6月23日の午前2時から4時までは、インターネットで特急券が予約できない。","6月23日の午前2時から4時までは、ホームページで時刻表や運賃表が見られない。","6月23日の午前4時以降、インターネットで特急券が予約できるようになる。","6月23日の午前4時以降、ホームページで時刻表や運賃表が見られるようになる。"], ans:0, exp:"①第1项正确：公告的核心注意事项＝点检期间预约系统暂停，网上无法预约特急券。②考点：通知的信息检索——区分「休止する対象（予約システム）」与「通常どおり（時刻表・運賃表）」。③排除：2与「時刻表や運賃表は通常どおり閲覧可能」矛盾；3恢复预约是事实但公告重点是「此期间不可用」；4时刻表本就可看，不是要传达的要点。④全文译文：见上文——6月23日凌晨2点至4点进行系统点检，期间网上无法预约特急券；首页的时刻表、运费表仍可正常查阅。", t:""},
  {type:"read", src:"N2真题·2024年7月（jlpt247整理）·問題10短篇", q:"オトシブミという虫について、筆者はどのように述べているか。", passage:"新緑の時期に森を歩くと、地面に小さなロールキャベツ状の物体が落ちているのを見かけます。しばしば一か所に大量に落ちていて、とてもよく目立ちます。これはオトシブミという小さな甲虫の仲間が、自分の幼虫のためにつくったものです。この虫のメスは、産んだ卵を木の葉で丁寧に包んでから地面に落とす習性をもちます。中で孵った幼虫は、内側からこの巻いた葉を食べて成長します。幼虫にとっては、この葉巻きは隠れ家であるとともに食料なわけです。（注1）ロールキャベツ：キャベツで肉を包んだ料理 （注2）甲虫：虫の一種 （注3）習性：ここでは、特徴的な性質 （注4）孵った：ここでは、卵から生まれた", opts:["食料を木の葉で包んで落とし、幼虫はそれを見つけて食べる。","木の葉と卵を落とし、生まれた幼虫は食料をその葉で巻いて隠す。","卵を木の葉で包んで落とし、生まれた幼虫はその中でその葉を食べる。","落ちている木の葉に卵を産んで包み、幼虫はその中で生まれて育つ。"], ans:2, exp:"①第3项正确：雌虫把卵用树叶包好后落地，孵化的幼虫在卷叶内从内侧吃叶成长。②考点：短篇——按「产卵→包む→落とす→孵化→食べる」的动作顺序逐项核对。③排除：1主体与对象错（包的是卵不是食料）；2不是「葉と卵一起落下」，也不是幼虫去卷叶；4不是把卵产在已落地的树叶上，而是产卵后包好再落。④全文译文：初夏的森林地面上常见像迷你卷心菜卷的小球，那是奥西布甲为幼虫所做：雌虫将产下的卵用树叶仔细包好后落到地面，孵出的幼虫在卷叶中从内侧吃叶长大——卷叶既是庇护所，也是食物。", t:""},
  {type:"read", src:"N2真题·2024年7月（jlpt247整理）·問題10情報検索", q:"このメールの用件は何か。", passage:"【件名：軽量ホチキスcx35 新色見本のお願い／JC文具 池西秋子】お世話になっております。JC文具の池西です。昨日、商品「軽量ホチキスcx35」の見本が2個届きました。機能性とシンプルなデザインは社内で評価が高く、取り扱い商品に加える方向で検討を進めております。同封されていた最新のカタログによると、来月から新色として3色が追加発売され、全部で5色になるとのことですので、新色の見本も送付していただけないでしょうか。代金が必要な場合は、お支払いします。取り扱うことが正式に決定しましたら、まずは5色を20個ずつ注文する予定です。よろしくお願いいたします。", opts:["見本として5色すべての商品を送ってほしい。","見本として新色の3個を追加で送ってほしい。","見本の代金としていくら支払えばいいか教えてほしい。","商品5色を20個ずつ注文できるかどうか教えてほしい。"], ans:1, exp:"①第2项正确：请求句是「新色の見本も送付していただけないでしょうか」＝请追加寄送新色（3色）样品。②考点：邮件用件——区分「请求（寄新色样品）」与「附带说明（代金可付、确定后订5色各20个）」。③排除：1已有2个样品，要的是新色；3支付代金是附带条件，不是用件；4「20個ずつ注文する予定」是自己的计划，不是向对方确认能否下单。④全文译文：见上文——已收到2个样品，因下月将新增3色共5色，请（追加）寄送新色样品；若需费用我们支付，正式确定后将先按5色各20个下单。", t:""},

  // ==================== 読解：中篇 / 統合理解 / 主張一致（read）====================
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題11中篇", q:"「そのようなとき」とはどのようなときか。", passage:"（将棋のプロが書いた文章）将棋の世界には、「不調も三年続けば実力」という言葉があります。自分自身が「自分には実力があるが、今は調子が悪いだけだ」と考えていたとしても三年も結果を出せなければ、それが本人の持っている実力である、という結構シビアな言葉です。仮に、不調の原因が現在の能力、実力であれば、自分の努力や練習が足りないということなので、頑張ってスキルや能力を上げ、実力をつければいいということになります。新しい戦法を勉強するなど懸命に努力をして、基本的な力を身につけるしかありません。しかし、どのような物事でも、今日一生懸命やったからといって、明日すぐに結果が出るということはありません。やっていることは間違っていないし、方向性も正しい。それでも成果が出ていないときこそが、「不調」ということになります。そのようなときは、まず気分を変えることです。…（中略）…たとえば、今までの生活習慣を変えてみる。早起きをしてみる、新しい趣味を始めてみる。あるいは服装を変えて、気持ちを切り替える。（注1）シビアな：厳しい （注2）スキル：ここでは、技術 （注3）モチベーション：やる気 （注4）図る：ここでは、する （注5）メリハリ：ここでは、変化", opts:["努力や練習が不足して、結果が出ていないとき","どのような結果を出せばいいか分からないとき","実力があっても、結果につながらないとき","やるべきことをやっても、結果につながらないとき"], ans:3, exp:"①第4项正确：「やっていることは間違っていないし、方向性も正しい。それでも成果が出ていないときこそが、『不調』」＝该做的都做了、方向也对，却仍无成果。②考点：指代题——「そのようなとき」回指前一句对「不調」的定义。③排除：1若真因努力不足，那属于作者假设的「实力原因」，不是此处定义；2与「方向性も正しい」矛盾；3「実力があっても」是作者要纠正的自我安慰，不是定义句。④译文要点：将棋界有「不调持续三年便是实力」的严苛说法。若不调真源于实力，就该加紧练习提升；但很多时候方向没错、也在努力，却仍无成果——这才是「不调」。这时应先转换心情，从小处改变生活习惯。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題11中篇", q:"筆者によると、不調のときはどうすればいいか。", passage:"（同上文・将棋のプロの「不調」論）…そのようなときは、まず気分を変えることです。どうしてもモチベーションが下がりやすくなっているので、気分転換を図る。つまり、何かを変えてみればいいということです。これは本当に何でもいいのです。ただし、調子は悪いので、いきなり大きなことではなく、小さなことから始めるのが良いでしょう。たとえば、今までの生活習慣を変えてみる。早起きをしてみる、新しい趣味を始めてみる。", opts:["原因を考えて新しいやり方を取り入れる。","結果がすぐに出ることから始める。","気分が変わるようなことをする。","生活を大きく変化させる。"], ans:2, exp:"①第3项正确：「まず気分を変える…気分転換を図る。つまり、何かを変えてみればいい」＝做能转换心情的事。②考点：主张一致——直接取末段的建议句。③排除：1原文说「やっていることは間違っていない」，不需要换方法；2须「小さなことから」开始，不是追求立刻见效；4「いきなり大きなことではなく」明确排除大变化。④译文要点（同上）：不调时先转换心情，试着改变点什么——从早起、开启新爱好等小事做起，逐步找回节奏。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題11中篇", q:"大勢の前で自分の意見を述べることについて、筆者たちの場合はどうだったか。", passage:"（今の若い人について書かれた文章）大勢の前で意見を述べるのは誰でも緊張する。うまく伝えられるかどうかと思う不安はあるから気後れする人もいる。それは、いつの時代も変わらないと思う。ただ、私たちの場合は、うまく話せないからと尻込みする者はいたが、自分の考えを言うことを嫌がる者はあまりいなかった。というのは、仲間との議論はみんながやっていたからだろう。私は別に議論がいいと言っているわけではない。ただ、自分が感じることや考えることを言って、友だちの意見を聞くことは、自分の考えを確かなものにしていくためには欠かせないと思うので、議論という言い方をしているだけなのである。（注1）気後れする：消極的になる （注2）尻込みする：不安になってやろうとしない", opts:["仲間との議論より緊張するので、嫌いな人が多かった。","仲間との議論に慣れていたので、発言を避ける人は少なかった。","仲間との議論を多くしていたので、みんな積極的に意見を言った。","仲間との議論をあまりしなかったので、うまく意見を言える人が少なかった。"], ans:1, exp:"①第2项正确：「うまく話せないからと尻込みする者はいたが、自分の考えを言うことを嫌がる者はあまりいなかった。というのは、仲間との議論はみんながやっていたから」＝因为人人参与讨论，回避发言者很少。②考点：内容一致——注意「～者はいたが、～者はあまりいなかった」的让步结构及其理由句。③排除：1文中没有「讨论比发言更紧张」的比较；3原文只说「大家都讨论」，没说「人人踊跃发言」；4与「みんながやっていた」相反。④译文要点：在人前发言人人都紧张，我们那时也有人因怕说不好而退缩，但很少有人不愿表达自己——因为伙伴间人人都在讨论。作者并非鼓吹讨论，只是认为说出所想、听取朋友意见，是让自己的想法变得确切所不可或缺的。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題11中篇", q:"今の若い人たちが議論をしない理由として、筆者の考えに合うのはどれか。", passage:"（同上文）ところが、今は中高生に限らず若い人全体の中に、まったくと言っていいほど議論がない。…以前、若い人を取材して、なぜ言わないのかと訊いたときの返事は、「人にはそれぞれ考え方があるのだから、とやかく言うことはできない」というものだった。これは、あたかも相手を尊重している「個人主義」のように聞こえるが、気のおけないはずの親しい友だちに対してもやっているのは不自然である。本当は、「自分の言うことに反対されて傷つくのがいやだから、相手の言うことにも反対しないわけ」で、結局、自分がかわいいのであり、傷つきたくないからなのだ。（注）とやかく：良いとか悪いとか", opts:["人の考えを聞いても、自分の考えは変わらないと思うから","自分が何か言うことで相手を傷つけたくないから","自分の考えに反対されて、いやな思いをしたくないから","自分の考えを相手に理解してもらうことは難しいと思うから"], ans:2, exp:"①第3项正确：「本当は、『自分の言うことに反対されて傷つくのがいやだから、相手の言うことにも反対しないわけ』」＝怕自己的话被反对而受伤，索性也不去反对别人。②考点：主张一致——「本当は」引出的真心话即答案。③排除：1作者认为表达正是「让想法变确切」的手段，无此说；2「不反驳对方」只是表层现象，作者追问的是「为何连表达自己都放弃」，根源是怕自己受伤；4文中未提「被理解很难」。④译文要点：如今不分中学生高中生，年轻人几乎不争论。他们说「每个人想法不同，不该多嘴」，看似尊重他人，但对亲密朋友也这样就不自然——其实是怕被反对而受伤，于是也不反对别人；说到底，是心疼自己、不想受伤。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題11中篇", q:"「①危険」とあるが、どのような点が危険か。", passage:"読書は、本の書き手や登場人物のワールドが自分の中に根づくことで、人生を豊かにしていくことができるものです。読書でワールドを増やしていけるのです。一方で、他者が自分の中に入り込む怖さもあります。自分よりはるかに思考力がある人の考えを読み、その人が深く入り込んできたら……。自分がなくなってしまうくらい影響を受けるかもしれません。読み方を間違えれば①危険でもあるのです。（中略）言葉を使っているというのもポイントで、著者の思考をなぞることができてしまう。それだけ深いレベルで影響を受けやすいのです。そう考えると、場合によっては「批判的に読む」ことも必要でしょう。（中略）「どっぷり読書」も、それはそれで②いいものです。その世界にどっぷりはまることで、思考が深まる面もあります。そのうえで批判的に読む。（中略）一人の作家に入れ込んで、その作家のものばかり読んでいると、どうしても視点が偏りがちになります。（注1）ワールド：世界 （注2）なぞる：ここでは、追う （注3）ナナメに：ここでは、悪い点を探そうとして （注4）どっぷりはまる：深く入り込む （注5）入れ込む：夢中になる （注6）ジャンル：分野", opts:["著者の考えに疑問を持つこと。","著者の考えに支配されてしまうこと。","著者の考えを読み間違えてしまうこと。","著者の考えを理解することで満足してしまうこと。"], ans:1, exp:"①第2项正确：「自分がなくなってしまうくらい影響を受ける」「著者の思考をなぞることができてしまう。それだけ深いレベルで影響を受けやすい」＝可能被作者的思考深度吞没、支配。②考点：指代题——「危険」的内容由前句「他者が自分の中に入り込む怖さ」与后句「思考をなぞってしまう」共同界定。③排除：1原文未说「产生疑问」是危险；3不是读错，而是读得太顺畅反而全盘接受；4文中未提「理解后就满足」的问题。④译文要点：读书能拓宽内心世界，但也有让他者侵入的危险——若对方思考力远胜于你，你可能深受支配；因为使用语言，你还能一路追摹作者思路，更易深度受影响。故有时须批判地读；但沉浸式阅读也能深化思考，之后再批判性地读，并广泛涉猎不同作家与类型以免视角偏狭。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題11中篇", q:"長く同じ活動を行ってきた組織について、筆者が挙げている問題点は何か。", passage:"（企業の経営者に向けて書かれた文章）長く同じ活動を行ってきた組織には、安定的な動きができるという長所があります。ところが、こういう組織には同時に、ある一つの方向からの固定的な見方しかできないという欠点もあります。この欠点はなかなかやっかいなものです。こうした見方が組織内に一度根づいてしまうと、なかなか変えることができない難しさがあるからです。よそから見れば危険極まりない状態なのに、組織の中では誰もそれにまったく気づかないということが起こるのはそのためです。これは②組織を支配する「気」が原因です。言葉を変えると、囲まれた本人は気づいていない、空気や雰囲気、あるいは文化といったものといえます。（中略）この状況を変えることができるのは、じつはトップだけです。トップがやらなければならないのは、組織全体を包んでいる「気」に惑わされないことです。（注1）根づく：定着する （注2）危険極まりない：非常に危険な （注3）惑わされる：迷わされる", opts:["組織の中に間違った見方をしている人が多いことに誰も気づかないこと。","組織が非常に危険な状態なのに、そのことを誰も言いだせないこと。","組織全体が同じ見方をしていて、危ない状況であることに誰も気づかないこと。","長く同じ活動を行っていることに、誰も疑問を持ろうとしないこと。"], ans:2, exp:"①第3项正确：「よそから見れば危険極まりない状態なのに、組織の中では誰もそれにまったく気づかない」，原因是固定看法已在整个组织内扎根。②考点：中篇内容一致——问题点＝全员同调、外人看来危险而内部无人察觉。③排除：1不是「个别人错了」，而是所有人被同一种固定看法笼罩；2原文没说「没人敢说」；4「长年做同一件事」本身是长所，问题出在视角固定。④译文要点：长期从事同一活动的组织虽稳定，却容易只有一种固定看法，一旦扎根就极难改变——外人看来危险至极，内部却无人察觉，元凶是笼罩组织的「气」（氛围与文化）。只有高层不被其迷惑、反而直面不愿看的东西，准确把握全局，才能引导组织走向正确方向。", t:""},
  {type:"read", src:"N2真题·2024年7月（jlpt247整理）·問題11中篇", q:"このような工夫とは、どのようなことか。", passage:"（スマホと情報について書かれた文章）ほとんどの人が、スマホやタブレットを通して、大量のSNSやネットニュースを毎日見ていることでしょう。多くの人がその膨大な情報を読むことあるいは見ることに、かなりの時間を費やしていて、ネット上の情報に追われている印象すら受けます。その結果、じっくり考える時間がどんどん少なくなっているようにも感じられます。また、大量の情報がネット上に流されるようになった結果、自分に都合の良い情報にしか接しない人が増えてきています。技術革新のおかげではあるのですが、SNSやネットニュースでは、その人の履歴から判断して、その人が関心を持っていると思われる情報やニュースが目につくところに流れるような工夫がされています。このような工夫はとても便利なことで、それによって時間が節約できたりする面は確かにあります。（中略）しかし、人々が見たいものだけを見て、信じている情報だけに接すると、発想が固定化してしまい、新しい進化が生まれにくくなってしまいます。（注1）費やす：使う （注2）技術革新：技術の進歩 （注3）履歴：ここでは、インターネット上の情報の閲覧の記録", opts:["情報を要約して、短時間で大量に見られるようにすること。","多くの人が関心を持っている情報を優先的に流すこと。","見る人が自分では探せない情報を選んで、提供すること。","見る人の興味の傾向に合わせて、情報を提供すること。"], ans:3, exp:"①第4项正确：「その人の履歴から判断して、その人が関心を持っていると思われる情報やニュースが目につくところに流れるような工夫」＝依据浏览记录按个人兴趣推送。②考点：指代题——「このような工夫」回指前句的推送机制。③排除：1不是做摘要功能；2不是「多数人关心」，而是「本人」的履历；3「自己找不到的信息」文中未提。④译文要点：多数人每天用手机平板刷大量SNS与网媒，被信息追着跑、深度思考的时间越来越少，也只接触对自己有利的信息；平台依据浏览履历把个人可能感兴趣的内容推到显眼处——虽便利省时，但只看想看的、只信信的，会让思路固化、难有新意。", t:""},
  {type:"read", src:"N2真题·2024年7月（jlpt247整理）·問題11中篇", q:"大量情報社会について、筆者の考えに合うのはどれか。", passage:"（同上文・大量情報社会について）そう考えると、この大量情報社会においては、いかにうまく情報を処理していくかがとても大事なことがわかります。また、大量情報を、一部だけ最初から抜き出して把握するのではなく、偏りがない形で、大量に処理することも必要です。", opts:["発想が固定化しないように、大量の情報を工夫して処理しなければならない。","思想的に偏りのある考えでも、工夫してうまく処理しなければならない。","必要な情報を選ぶために、大量の情報をうまく処理しなければならない。","時間が偏りなく大量の情報を処理しなければならない。"], ans:0, exp:"①第1项正确：作者主张不能一开始就只截取一部分，而要无偏倚地大量处理信息，以避免「発想が固定化」。②考点：主张一致——前文的问题意识（发想固定化）＋本段的对策（偏りがない形で、大量に処理）。③排除：2作者反对的是「只接触有偏信息」，不是要我们去处理偏见；3「挑选必要信息」恰是作者批评的「一部だけ最初から抜き出す」；4「时间不偏」无中生有。④译文要点（同上）：在海量信息社会，如何处理信息至关重要——不能一开始就只挑一部分，而应无偏倚地大量处理，这样才能避免思路固化。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 2（jlpt247整理）·問題12統合理解", q:"AとBは、それぞれどのように運動していると述べているか。", passage:"A かつて私は仕事が忙しく、運動が続けられずに悩んでいた。自分に合った運動方法を探しているうちに、無理やり時間を確保するよりも、日常生活の中に取り入れたほうがいいと思うようになった。現在は通勤や買い物に行くとき、車を使わずに歩いたり、エレベーターではなく階段を利用したりするようにしている。また、歩くときは、ふだんより速足で歩くようにしている。そうすれば時間が取れなくても、毎日運動ができる。体を動かすことを習慣にすることが大事だと思う。運動には体の健康だけでなく、ストレスを解消するなど心の健康を保つ効果もある。これからもずっと無理せずに続けていきたい。 B 私は、運動を始めてもなかなか続けられなかった。そんなとき、仕事のあとで仲間と一緒にランニングを始めた。仲間と互いに成果を報告し合ったり、情報交換したりすることで、運動への関心を高めることができた。また、仕事で疲れて運動るのが面倒なときや運動するのがつらいと感じるときでも、話を聞いてもらうことで、気分転換ができた。確かに、一人で運動するほうが自分のペースでできるので気楽だという人もいる。しかし、一人では、やる気がしないときに続けることは難しい。仲間と一緒に楽しく運動すれば、頑張ろうという意欲がわいてくる。運動は続けていくことに意味があると思う。", opts:["AもBも、さまざまな運動に取り組んでいると述べている。","AもBも簡単にできる運動をしていると述べている。","Aは生活の中でできるだけ長く運動していると述べ、Bは仲間と成果を競いながら運動していると述べている。","Aは生活の中で体を動かしていると述べ、Bは仲間と一緒に運動していると述べている。"], ans:3, exp:"①第4项正确：A把运动融入日常生活（步行、爬楼梯、快走），B和同事一起跑步——与D的前后两半完全对应。②考点：統合理解——先分别概括A、B的运动方式再逐项匹配。③排除：1两人各自形式单一（走路/跑步），不是「各种各样」；2A确实是日常可做的运动，但B强调的是「同伴」而非简便，概括不完整；3A并非「尽量延长运动时间」，B也不是「与同伴竞争成果」，而是互相汇报、交换信息。④译文要点：A：忙得坚持不下来后，决定把运动融入日常生活——通勤购物走路、改走楼梯、加快步速，不挤时间也能天天活动身体，认为养成习惯最重要，且运动还能解压、有益心理健康，打算毫不勉强地一直继续。B：曾屡屡半途而废，后来和同事下班一起跑步——互相汇报成果、交换信息提升了兴趣；疲惫偷懒时靠倾诉转换心情。一个人虽自在，但没干劲时难以坚持；和大家一起快乐运动才会产生努力的意欲——运动贵在持续。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題12統合理解", q:"感謝の手紙を書く際に形式的な表現や文を使うことについて、AとBはどのように述べているか。", passage:"A 感謝の手紙を書くとき、どうしたら相手に自分の思いをうまく伝えられるだろうか。手紙というと、始まりや終わりの決まり文句など、形式的な表現や文を使わなければならないと思われがちだ。そのような表現や文を使うことは、確かに表面上は相手のことを大切に考えているような印象を与えるが、実は失礼にならないように自分を飾っているだけなのではないか。思いを伝えるには、手紙を読んだ相手の気持ちを想像することが大事になる。そのうえで、形式的な表現や文を使わずに自分の言葉で書けば、思いが相手の心にまっすぐ届く。 B 感謝の思いは、手紙で伝えるのがいいと思う。ふだんとは違う丁寧に書かれた文章から、真剣な気持ちが伝わるからだ。手紙で思いを伝えるには、始まりや終わりの決まり文句など、形式的な表現や文を、正しく理解して使ったほうがいい。相手と自分との関係に合わせて適切に使い、相手が読んでどう感じるかもよく考えながら書くことが重要だ。手紙は個人なものだから、どのように書いても自由だと思うかもしれない。しかし、形式的な表現や文を正しく使い、礼儀正しい印象を持ってもらうことで、自分が伝えたいこともしっかり伝わるものだ。", opts:["AもBも、礼儀正しすぎる印象を与えるのであまり使わないほうがいいと述べている。","AもBも、自分の思いをきちんと伝えるためにできるだけ使ったほうがいいと述べている。","Aは自分をよく見せようとしているだけなので使わないほうがいいと述べ、Bは使い方を理解してうまく使ったほうがいいと述べている。","Aは正しく使うのは難しいので使わないほうがいいと述べ、Bは真剣な気持ちが伝わるので使ったほうがいいと述べている。"], ans:2, exp:"①第3项正确：A认为套话「実は自分を飾っているだけ」，应弃用、用自己的话写；B认为「正しく理解して使ったほうがいい」，按关系恰当使用。②考点：統合理解——针对同一话题（形式表达），分别提取A、B的立场再比对。③排除：1B主张使用，非「都少用」；2A主张不用，非「都尽量用」；4A的理由不是「难用」，B的主要理由也不止「显得认真」。④译文要点：A：写感谢信不必拘泥开场结尾的套话，那只是包装自己；设身处地想象收信人的心情、用自己的话写，心意才能直达。B：感谢之情以书信传达为好，郑重的文字能传达认真之心；套话要正确理解、视双方关系恰当使用，并考虑对方感受——给人有礼的印象，自己想传达的心意才真正传得到。", t:""},
  {type:"read", src:"N2真题精选·JLPT Pro 3（jlpt247整理）·問題13主張一致", q:"①なかなか決断できない人とあるが、なぜ決断できないのか。", passage:"（決断力について書かれた文章）決断力がないと、いつも誰かの指示や命令に黙って従って生きていくしかない。そんな人生は誰も望まないだろう。…このことを理解するためには、逆に①なかなか決断できない人を考えてみればいい。決断しなければならない場面で決断できない人は、何を考えているのだろうか。たとえば「行く」か「行かない」かという決断をするときに、その見通しをつけたいと思っているのだ。行けばどうなるか、行かないとどうか。つまり「正しい決断をしたい」と思っているのだ。だが、この気持ちこそが決断を遅らせる最大の原因である。（中略）哲学者のアミエルという人が「決心する前に、完全な見通しをつけようとする者は、決心することができない」といっている。そのとおりなのだ。（中略）うまくいかなかった原因は決断にあったのではなく、その後の処し方が悪かったからだ。決断ですべてが決まるわけではない。決断した後の考え方や行動が大切。だが、決断しないことには何事もはじまらない。（注1）要は：大事なことは （注2）エイヤッと：ここでは、思い切って （注3）処し方：ここでは、対応 （注4）正体：本当の姿", opts:["自分が正しい決断ができるとは思えないから。","一度決断したら変えられないと思って迷うから。","その場で決断すべきことかどうかわからないから。","間違った決断をしたくないと思って考えすぎるから。"], ans:3, exp:"①第4项正确：「その見通しをつけたいと思っている…『正しい決断をしたい』と思う。だが、この気持ちこそが決断を遅らせる最大の原因」＝想事先看清结果、想做出正确的决断，因而想得太多。②考点：問題13（主张一致/指代）——「①」的原因在紧接着的句子中展开，须抓「最大の原因」这一标记。③排除：1不是怀疑自己的能力，而是想确保「正确」；2文中未提「一旦决定就不能改」；3不是判断不了该不该决断，而是想先看清行与不行的结果。④译文要点：没有决断力就只能永远听命于人。所谓决断力其实只是「该决定时就决定」的勇气；迟迟不决的人总想事先看清结果、想做出正确决断——正是这份心意让决断一再拖延。不必强求看透，干脆定下来即可；决定之后的处理方式与行动才是关键，但不决断则万事不始。", t:""},

  // ==================== 聴解（listen）====================
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題3概要理解", q:"部長は何について話していますか。", passage:"", opts:["採用の面接で重視すること","今年の応募者の特徴","採用人数を増やした理由","入社後の新入社員の活躍"], ans:0, exp:"①第1项正确：全段围绕「面接では～を見てください」这一选考标准展开（专业知识与经验、灵活应变力、对本公司发展的想象）。②考点：問題3（概要理解）——抓住反复出现的框架句「面接では…見てください」，主题是「面试看重什么」。③排除：2「応募者数が多い」只是背景信息，未展开应聘者特征；3增员是前提，讲话重点是「怎么选」而非「为什么增」；4讲的是入职前的面试，不是入社后的表现。④全文翻译：人事部会议上部长说：今年计划大幅增加有实务经验的录用，因应聘者很多，请认真选拔。面试时不仅要看专业知识与经验的有无，还要看能否灵活应对各种环境；另外也要看应聘者是否清楚地想象过自己在本公司的发展。", t:"人事部の会議で部長が話しています。 男：えー、今年度は実務経験のある方の採用を大幅に増やす予定ですが、応募者数がかなり多いのでしっかり選考してください。面接では専門的な知識や経験の有無はもちろんのこと、いろいろな環境に柔軟に対応できる力があるかを見てください。それから、応募者がわが社での活躍をどのようにイメージできているかという点も見てください。 部長は何について話していますか。 1.採用の面接で重視すること 2.今年の応募者の特徴 3.採用人数を増やした理由 4.入社後の新入社員の活躍"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題3概要理解", q:"ラジオで女の人は何について話していますか。最もよいものを選びなさい。", passage:"", opts:["ハチミツをテーマにした物語","ハチミツに含まれる栄養","ハチミツの採り方","食料としてのハチミツの歴史"], ans:3, exp:"①第4项正确：从西洋2000年前的食用记录、神话，讲到日本8世纪的记载与明治时期养蜂普及——讲的是蜂蜜作为食物的历史。②考点：概要理解——抓时间轴词汇（2000年以上前・8世紀・明治）判断主题为「历史」。③排除：1没讲任何故事内容；2通篇未提营养成分；3未涉及采集方法（只提明治后「採りやすくなった」这一普及背景）。④全文翻译：广播里说：被视为有益健康的蜂蜜自古以来就受人喜爱。在西方，2000多年前的文献中就有当时人们食用蜂蜜的记录，还有神话中教授蜜蜂造蜜的神。日本8世纪的文献中也有蜂蜜的记载，但很长时期只有少数人能享用；明治以后，引进了容易饲养的西方蜜蜂，采蜜变得容易，蜂蜜才一下子在普通百姓中普及开来。", t:"ラジオで女の人が話しています。 女：健康にいいと言われるハチミツは古くから人々に愛されてきました。西洋では2000年以上前の書物に当時の人がハチミツを食べていた記録を見ることができます。また、西洋のある神話の中にもハチミツの作り方を教えたとされる神様が登場します。 日本では8世紀の書物にハチミツに関する記録がありますが、ハチミツは長い間一部の人しか口にできない貴重なものでした。明治になると育てやすいとされる西洋ミツバチという種類の蜂が輸入され、ハチミツが採りやすくなったことで一般の人の間でも一気に普及したのです。 女の人は、何について話していますか。 1.ハチミツをテーマにした物語 2.ハチミツに含まれる栄養 3.ハチミツの採り方 4.食料としてのハチミツの歴史"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題3概要理解", q:"出版社の人は、何について話していますか。", passage:"", opts:["大人にとっての絵本の魅力","大人に選ばれる絵本のテーマ","親子で絵本を読むことのメリット","絵本が子供に与える影響"], ans:0, exp:"①第1项正确：围绕「大人が読んでも心に響く」「疲れた心をリラックスさせる」「大人でも十分に楽しめる」——讲的是绘本对大人的魅力。②考点：概要理解——主题句是「自分のために絵本を購入する大人が増えている」及其展开。③排除：2没讲题材/主题偏好；3亲子共读完全没提；4讲的是大人而非对孩子的影响。④全文翻译：电视采访绘本出版社的山田先生。男：最近似乎越来越多大人为自己买绘本。女：是的，绘本用小孩也能懂的简单语言写成，大人读了也会被打动；温暖的插画和直抵内心的话语据说有让疲惫的心放松的效果。男：页数少、短时间能读完，对忙碌的大人来说也是容易入手的理由之一吧。女：是啊。以前人们总认为绘本是读给孩子听的，其实大人也完全能享受其中。", t:"テレビでアナウンサーの男の人と絵本の出版社の人が話しています。 男：今日は子供向けの本の出版社、さくら出版の山田さんにお話を伺います。最近、自分のために絵本を購入する大人が増えているそうですね。 女：はい。絵本は子供でもわかるシンプルな言葉で書かれていますが、大人が読んでも心に響くものがあるようです。暖かなイラストや心にまっすぐ届く言葉で描かれた絵本は疲れた心をリラックスさせる効果があるという声が聞かれます。 男：なるほど。ページ数も少なく、短時間で読めるというのも忙しい大人にとっては手に取りやすい理由の１つなのかもしれませんね。 女：ええ。以前は絵本というと子供に読んで聞かせるものと思われがちましたが、大人でも十分に楽しめるんだなと感じています。 出版社の人は、何について話していますか。 1.大人にとっての絵本の魅力 2.大人に選ばれる絵本のテーマ 3.親子で絵本を読むことのメリット 4.絵本が子供に与える影響"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題3概要理解", q:"映画監督は何について話していますか。", passage:"", opts:["最近の映画研究の傾向","自分の映画におけるストーリーの組み立て方","人気がある映画の共通点","映画製作に対する姿勢の変化"], ans:1, exp:"①第2项正确：「僕がオリジナルの映画の構成を考える時は3つの要素で物語を展開させます」——问题提示、意外展开、最终解决＋主人公成长，讲的是他自己作品的故事结构。②考点：概要理解——首句「僕が～構成を考える時は」点题，后文全是展开。③排除：1没谈研究趋势；3讲的是自己影片的构成，不是「人气电影的共同点」；4通篇无态度变化。④全文翻译：讲演会上电影导演说：我从小就想从事电影制作，自己研究各种故事展开方式，形成了如今的风格。构思原创电影时，我用三个要素推进故事：首先是提出问题——出现需要解决的困境；接着主人公解决问题的过程中出现意外展开，最终问题得以解决，并在过程中让主人公成长。恋爱片也好历史片也好都是如此。", t:"講演会で映画監督が話しています。 男：僕は子供のころから将来、映画製作の仕事がしたくて自分なりに様々な映画のストーリー展開を研究し、今のスタイルに行きつきました。僕がオリジナルの映画の構成を考える時は3つの要素で物語を展開させます。 まず最初に問題の提示。つまり、何か困ったことが起きたりして解決すべきことを示します。そして主人公が問題解決に向かう中で予想外の展開があって、最終的に問題が解決する。その過程で主人公を成長させるんです。恋愛ものでも歴史ものでもそれは共通していますね。 映画監督は何について話していますか。 1.最近の映画研究の傾向 2.自分の映画におけるストーリーの組み立て方 3.人気がある映画の共通点 4.映画製作に対する姿勢の変化"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題3概要理解", q:"社長が言いたいことは何ですか。", passage:"", opts:["社員１人１人に電気を節約してほしい","電気製品を省エネのものにしたい","日光で発電する機械を使いたい","会社の設備を長く大切に使ってほしい"], ans:0, exp:"①第1项正确：社长先否定了太阳能等设备方案，提出「社員全員に無駄をもっとなくすことを考えてもらいたい」，并举例关灯、走楼梯、空调温度，即希望每位员工节电。②考点：概要理解——抓「その前に～てもらいたいんです」的真正诉求句。③排除：2省エネ改造是过去已完成的事；3太阳能只是被提议、社长并未采纳；4主题是节电，不是延长设备寿命。④全文翻译：公司里社长对女员工说：这几年公司规模没扩大，电费却一个劲儿上涨。之前已把照明换成节能型……女：那要不要开始太阳能发电？社长：在那之前，我想先让全体员工都想想怎么减少浪费——比如别让会议室的灯一直亮着、能走楼梯就走楼梯，还有冷房温度有时调得太低了吧？大家要有意识地一起做。女：好的，我用社内通知传达。", t:"会社で社長と女の社員が話しています。 男：本田さん。ここ数年、会社の規模が大きくなったわけでもないのに電気代の支払いが増える一方なんですよね。 女：そうですね。これまで照明や電気製品を省エネタイプに替えてきましたが…。以前検討していた太陽光発電も始めてみましょうか。 男：うーん、その前に社員全員に無駄をもっとなくすことを考えてもらいたいんです。会議室の電気をつけっぱなしにしないとか１つ階を移動する程度ならできるだけ階段を使うとか。あとは、時々冷房の温度設定が低すぎるときがありますよね？みんなで意識してやっていかないといけないですよ。 女：そうですね。そのように社内連絡で伝えます。 社長が言いたいことは何ですか。 1.社員１人１人に電気を節約してほしい 2.電気製品を省エネのものにしたい 3.日光で発電する機械を使いたい 4.会社の設備を長く大切に使ってほしい"},

  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】こう熱帯夜が続くとエアコンは欠かせませんよね？最もよい返事を選びなさい。", passage:"", opts:["エアコンはなくてもいいんですか？","え？どうしてエアコンを使わないんですか？","エアコンつけて寝ないと寝れないですよね"], ans:2, exp:"①「欠かせませんよね？」＝离不开空调吧？是寻求同感的确认，回应「エアコンつけて寝ないと寝れないですよね」（不开空调都睡不着呢）承接同感，第3项恰当。②考点：問題4（即時応答）——反问句「～よね？」须以同感回应。③排除：1把「欠かせない（离不开）」曲解为「不需要」；2把陈述当成了疑问。④翻译：发言：这样的热带夜接连不断，空调都离不开了吧？恰当回应：不开空调都睡不着呢。", t:"こう熱帯夜が続くとエアコンは欠かせませんよね？ 1.エアコンはなくてもいいんですか？ 2.え？どうしてエアコンを使わないんですか？ 3.エアコンつけて寝ないと寝れないですよね"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】伊藤さん。２時から予定してた打ち合わせだけど、時間ずらしてもらえない？最もよい返事を選びなさい。", passage:"", opts:["あ、私はいつでも構いません","打ち合わせの時間を長くするんですか？","２時からで大丈夫です"], ans:0, exp:"①对方请求把会议时间往后挪，接受请求应回「あ、私はいつでも構いません」（啊，我什么时候都行），第1项恰当。②考点：即時応答——「～てもらえない？」的委托句须以答应作答。③排除：2把「时间ずらす（挪时间）」误解为「延长时长」；3「２時からで大丈夫」是拒绝改期，与请求相悖。④翻译：发言：伊藤，原定2点的碰头会，能把时间挪一下吗？恰当回应：啊，我什么时候都可以。", t:"伊藤さん。２時から予定してた打ち合わせだけど、時間ずらしてもらえない？ 1.あ、私はいつでも構いません 2.打ち合わせの時間を長くするんですか？ 3.２時からで大丈夫です"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】中野さん。中野さん、最近卓球部の練習休みがちだけどどうしたの？最もよい返事を選びなさい。", passage:"", opts:["試合が近いから休みたくないんだ","ごめん、ちょっとバイトが忙しくて","練習がないから１人でやってたんだ"], ans:1, exp:"①对方询问「最近经常缺席练习怎么了」，应回以理由致歉——「ごめん、ちょっとバイトが忙しくて」（抱歉，打工有点忙），第2项恰当。②考点：即時応答——「～がちだ＋どうしたの？」＝询问原因，答句须给理由。③排除：1答非所问（对方没问想不想练）；3「练习没有」与「缺席练习」矛盾。④翻译：发言：中野，你最近老是缺席乒乓球部的练习，怎么了？恰当回应：抱歉，我打工有点忙。", t:"中野さん。中野さん、最近卓球部の練習休みがちだけどどうしたの？ 1.試合が近いから休みたくないんだ 2.ごめん、ちょっとバイトが忙しくて 3.練習がないから１人でやってたんだ"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】もうすぐ会議の時間ですけど山本課長、昼ごはん食べに行ったきりですね。最もよい返事を選びなさい。", passage:"", opts:["まだ戻られてないんですか？","課長、これから昼食ですか？","あ、もう帰ってこられたんですか？"], ans:0, exp:"①「食べに行ったきりですね」＝去了吃午饭就再没回来，顺此逻辑应回「まだ戻られてないんですか？」（还没回来吗？），第1项恰当。②考点：即時応答——「～たきり（だ）」＝一去不回/此后无下文，须与「未归」呼应。③排除：2把「行ったきり」误解为「正要去」；3与「まだ」的事实相反。④翻译：发言：马上就要开会了，山本部长吃了午饭一直没回来呢。恰当回应：还没回来吗？", t:"もうすぐ会議の時間ですけど山本課長、昼ごはん食べに行ったきりですね。 1.まだ戻られてないんですか？ 2.課長、これから昼食ですか？ 3.あ、もう帰ってこられたんですか？"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】店長、修理を頼んでいた冷蔵庫ですが、買い替えるほかないそうです。最もよい返事を選びなさい。", passage:"", opts:["あー、直せないんですか","直せるんですね。良かったです","直せるかどうかまだわからないんですね"], ans:0, exp:"①「買い替えるほかない」＝只能换新，即修不好，回应「あー、直せないんですか？」（这样啊，修不好了吗？）正确承接，第1项恰当。②考点：即時応答——「～ほかない」＝除…别无他法（消极结论）。③排除：2把结论当成「能修」；3「还不知道能不能修」已过时，对方已给出结论。④翻译：发言：店长，拜托修理的冰箱，听说只能换新的了。恰当回应：啊，修不好了吗？", t:"店長、修理を頼んでいた冷蔵庫ですが、買い替えるほかないそうです。 1.あー、直せないんですか 2.直せるんですね。良かったです 3.直せるかどうかまだわからないんですね"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】課長の送別会、「出席、欠席に関わらず早く返事くれ」って小野さんが言ってたよ。最もよい返事を選びなさい。", passage:"", opts:["出る人だけ連絡すればいいんだね","行けないなら早めに返事するんだね","出席できない人は連絡いらないって思ってたよ"], ans:2, exp:"①「出席、欠席に関わらず早く返事くれ」＝无论出席与否都要尽快答复；第三项「出席できない人は連絡いらないって思ってたよ」（我还以为不来的人不用回呢）恰好点出与原话的出入，第3项恰当（即時応答常考「听反了/理解错」的接话）。②考点：即時応答——「～に関わらず」＝无论…都，须与「都要答复」对照理解。③排除：1曲解为「只有出席的人才联络」；2「行けないなら早めに返事」本身正确但不是对「原来理解有误」的接话——本题正确答案为第3项，说话人以自己的误解来接话（出题意图是选出与前提相符的自然回应，第3项与前提的对照最贴合）。④翻译：发言：小野说课长的欢送会「不管来不来都要尽快答复」哦。恰当回应：我还以为来不了的人不用回呢。", t:"課長の送別会、「出席、欠席に関わらず早く返事くれ」って小野さんが言ってたよ。 1.出る人だけ連絡すればいいんだね 2.行けないなら早めに返事するんだね 3.出席できない人は連絡いらないって思ってたよ"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】森さん。セミナー当日のお弁当、スタッフの分を含めて３０個予約をお願いします。最もよい返事を選びなさい。", passage:"", opts:["スタッフの分だけで３０個ですね","予約するお弁当は全部で３０個ですね","スタッフのお弁当は別に注文するんですね"], ans:1, exp:"①「スタッフの分を含めて３０個」＝含员工在内共30个，回应「予約するお弁当は全部で３０個ですね」（要订的便当一共30个吧）正确复述，第2项恰当。②考点：即時応答——「～を含めて」＝包括…在内，听清总数。③排除：1把「含」误听为「只」；3原句没有「另行订购」的意思。④翻译：发言：森，研讨会当天的便当，请连员工的一起共预订30份。恰当回应：要订的便当一共30份吧。", t:"森さん。セミナー当日のお弁当、スタッフの分を含めて３０個予約をお願いします。 1.スタッフの分だけで３０個ですね 2.予約するお弁当は全部で３０個ですね 3.スタッフのお弁当は別に注文するんですね"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】今日のサンプルのミーティングだけど、「部長抜きでやってくれ」って部長からメールが来たよ。最もよい返事を選びなさい。", passage:"", opts:["じゃ、部長が来てから始めよう","今日、部長来ないんだ","あー、今日はミーティング中止なんだね"], ans:1, exp:"①「部長抜きでやってくれ」＝部长不参加、你们自己开，回应「今日、部長来ないんだ」（部长今天不来啊）正确理解，第2项恰当。②考点：即時応答——「N＋抜きで」＝去掉…、不含…。③排除：1把「抜きで」误解为「等部长来了再开」；3「中止」原话未提。④翻译：发言：今天样品碰头会，部长发邮件说「你们别算我，自己开」。恰当回应：部长今天不来啊。", t:"今日のサンプルのミーティングだけど、「部長抜きでやってくれ」って部長からメールが来たよ。 1.じゃ、部長が来てから始めよう 2.今日、部長来ないんだ 3.あー、今日はミーティング中止なんだね"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】駅前のカラオケ、今度の土日に限り半額ってチラシで見たけど行かない？最もよい返事を選びなさい。", passage:"", opts:["毎週土日は半額なんだね。行こうか？","平日が半額になるなら平日だね","今度の週末だね。土曜でもいい？"], ans:2, exp:"①「今度の土日に限り半額」＝仅本周六日半价，回应「今度の週末だね。土曜でもいい？」（那就是这周末嘛，周六也行吧）正确把握「限り」的限定，第3项恰当。②考点：即時応答——「～に限り」＝仅限…。③排除：1把「今度の」误听成「毎週」；2原文没说平日半价。④翻译：发言：传单上说站前KTV仅这周六日半价，去不去？恰当回应：就是这周末嘛，周六也行吧。", t:"駅前のカラオケ、今度の土日に限り半額ってチラシで見たけど行かない？ 1.毎週土日は半額なんだね。行こうか？ 2.平日が半額になるなら平日だね 3.今度の週末だね。土曜でもいい？"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】課長、みどり社に来年のイベントへの協力を依頼しているんですが、返事が曖昧なんです。最もよい返事を選びなさい。", passage:"", opts:["改めてお礼のメールを送ってください","じゃ、私から聞いてみましょうか","受けてもらえて安心しました"], ans:1, exp:"①「返事が曖昧」＝对方答复含糊，需要进一步确认，回应「じゃ、私から聞いてみましょうか」（那我再去问问看吧）给出对策，第2项恰当。②考点：即時応答——问题提出型发言应答以「解决方案」。③排除：1事由是答复含糊，不是要道谢；3「我很安心」与含糊答复的困扰相反。④翻译：发言：课长，我请绿社协助明年活动，他们的回复含糊其辞。恰当回应：那我去问问看吧。", t:"課長、みどり社に来年のイベントへの協力を依頼しているんですが、返事が曖昧なんです。 1.改めてお礼のメールを送ってください 2.じゃ、私から聞いてみましょうか 3.受けてもらえて安心しました"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】２月にみんなで行くスキー旅行のサイト見たけど、来月になってからでないと申し込みできないって。最もよい返事を選びなさい。", passage:"", opts:["え？まだ時間あるのにもういっぱいなの？","じゃ、今月中に予約しなくちゃいけないんだね","そう。じゃ、来月になったらすぐ予約しよう"], ans:2, exp:"①「来月になってからでないと申し込みできない」＝必须进入下月才能报名，回应「じゃ、来月になったらすぐ予約しよう」（那下个月一开始马上订吧）正确，第3项恰当。②考点：即時応答——「～てからでないと～ない」＝不…就不行（必要条件）。③排除：1把必要条件误解为「名额已满」；2把「下月起」误为「本月内」。④翻译：发言：看了2月滑雪旅行的网站，说要到下个月才能报名。恰当回应：那下个月一开始马上订吧。", t:"２月にみんなで行くスキー旅行のサイト見たけど、来月になってからでないと申し込みできないって。 1.え？まだ時間あるのにもういっぱいなの？ 2.じゃ、今月中に予約しなくちゃいけないんだね 3.そう。じゃ、来月になったらすぐ予約しよう"},

  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題5综合理解", q:"混雑解消のためにまず何をすることにしましたか。", passage:"", opts:["イベントスペースに座席を作る","食べ終わった客に席を空けてもらうよう声をかける","早く席を空けた客に割引券を配る","フードコートの中の座席を増やす"], ans:2, exp:"①第3项正确：讨论中提议过A（利用活动区加座——因已被预定否决）、B（请吃完的客人让座——被认为像赶客、人手不足）、D（增加座席——桌距会变窄），最终社长决定「増員して、お客様に進んで席を空けてもらえそうな方法を試す、結果を見て増席を検討」，而让大家「积极主动让座」的办法正是C（30分钟内离席者赠下次可用的折扣券）。②考点：問題5（综合理解）——多方意见逐一出现，最终以最后总结句为准，且「その結果を見て」表明先试行C。③排除：A被「定期的に使用する予定が入っている」否决；B被女职员与社长以「追い出すよう」「無理がある」否决；D是后续再检讨的事项，不是「首先」做的。④全文翻译：会议讨论购物中心美食广场周末午餐拥堵问题。女提议用旁边的活动区加座——男1说已有定期使用安排很难；男2提议请吃完的人让座——女说像赶客，男1也说人手不足；男2又提议给30分钟内主动离席的客人发下次可用的折扣券（凭收据领券）——男1认为客人会积极让座，只是人手不够；女主张增加座位——男2担心桌距变窄。最后男1决定：先增加人手，并试行能让客人主动让座的方法，看结果再考虑是否增座。", t:"会議で上司と社員２人がフードコートの混雑について話しています。 男１：うちが運営している南ショッピングセンターなんですが、週末のランチタイムになるとフードコートが混雑して席が空くのを待ってる人がたくさんいるんですよね。何かいい案はありませんか？ 女：フードコートの横にイベントスペースがありますよね？何も置いていないし、あそこにも座席を作れたらいいんですが…。 男１：そうなんですが、定期的に使用する予定が入っているからちょっと難しいですよね。 男２：食事が終わった後ゆっくり座ってる方も多くて、それが混雑の一因になっています。だから食べ終わった人に声をかけて席を空けてもらうと言うのはどうですか？ 女：お客様を追い出すようにするというのはちょっと…。 男１：それにお客様が多い中、スタッフが声をかけて回るのは無理がありますね。 男２：じゃ、早く、例えば30分以内に席を空けてくれたお客様に次回使える割引券をお渡しするのはどうですか？食事は前払いだからレシートに買った時間が書いてありますよね。出る時、スタッフにそれを見せて券を受け取ってもらうようにするとか…。 男１：あぁ、お客様も積極的に席を空けてくれそうですね。今のスタッフの人数では対応が難しそうですが…。 女：やっぱり席を増やすのが優先と思います。今の広さのままでももう少し席を追加できるんじゃないでしょうか？ 男２：席と席の間が狭くなってしまいますよね？ 男１：うーん、そうですね。スタッフを増やすことにしてお客様に進んで席を空けていただけそうな方法を試してみましょう。その結果を見て、席を増やした方がいいか検討しましょうか。 混雑解消のためにまず何をすることにしましたか。 1.イベントスペースに座席を作る 2.食べ終わった客に席を空けてもらうよう声をかける 3.早く席を空けた客に割引券を配る 4.フードコートの中の座席を増やす"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題5综合理解", q:"男の人はまずどの会場に行くと言ってますか。", passage:"", opts:["第1会場：どなたでもできる体力測定","第2会場：健康づくりの体操の紹介","第3会場：健康な食生活の紹介・献立","第4会場：健康の悩みを医師が相談に応じる"], ans:0, exp:"①第1项正确：男士说想了解「在公司也能做的运动」，但最后改口「まずは今どれくらい体力があるか測ってもらおう」，即先去测体力的第1会场。②考点：問題5（综合理解）——同一人先后两个念头，最终决定以「まず～」的最后表态为准。③排除：2是他最初的想法（请教体操），被自己推翻；3他没有要改变饮食的意向；4是女伴要去的会场。④全文翻译（要点）：市健康活动现场介绍四个会场：1测体力年龄、2健康体操、3健康饮食、4医师咨询。男：想了解在公司也能做的运动……不过还是先测测自己现在有多少体力吧。女：我嘛还是去问每天的菜单。男：你不是说睡不好吗？不先去问问医生？女：啊对，那我先去那边（医师咨询）。", t:"市の健康イベントで市の職員が話しています。 女１：市民健康イベントにお越しいただきありがとうございます。館内には４つの会場がございます。第１会場では体力測定を実施しております。どなたにもできる簡単なテストでご自分の体力年齢を測定することができます。 第２会場では健康づくりに役立つ体操を紹介しております。職場や家庭で簡単にできるものからちょっと難しめのものまでご自分の体力に合わせて運動していただけます。ぜひ体験してみてください。第３会場では健康な食生活をテーマに毎日の献立や調理法を講師が紹介します。栄養が偏りがちな方におすすめです。第４会場では健康に関する悩みや相談に個別にお答えします。１時から４時まで医師がおりますのでこの機会をご利用ください。 男：へー、いろんなのがあるんだね。時間がない時に会社でもできる運動を教えてもらおうかな。最近運動してないし 女２：うん、いいんじゃない？スポーツジムに行く時間も取れないもんね。通勤途中や仕事中でも体を動かせたらたらいいね。 男：うん。まずは今どれくらい体力があるか測ってもらおう。頑張らなきゃって気になれるし。 女２：そう。私はやっぱり毎日の献立かな？一度食事を見直したいと思ってたの。 男：それより最近ぐっすり眠れないって言ってなかった？お医者さんに相談してみたら？ 女２：あ、そうだね。そっち先に行ってこよ。 質問１：男の人はまずどの会場に行くと言ってますか。 1.第1会場 2.第2会場 3.第3会場 4.第4会場"},
  {type:"listen", src:"N2真题听力原文·2024年12月（爱心日语整理）·問題5综合理解", q:"女の人はまずどの会場に行くと言ってますか。", passage:"", opts:["第1会場：どなたでもできる体力測定","第2会場：健康づくりの体操の紹介","第3会場：健康な食生活の紹介・献立","第4会場：健康の悩みを医師が相談に応じる"], ans:3, exp:"①第4项正确：女士先想去看每日菜单（第3会场），但被男士提醒「最近不是睡不好吗？不问问医生？」后改口「そっち先に行ってこよ」＝先去医师坐诊的第4会场。②考点：综合理解——主意改变的转折点「あ、そうだね」之后的最终表态才是答案。③排除：3是她最初的想法（被自己放弃）；1、2她没有提及要去。④全文翻译（要点）：见上——她原本想去第3会场看看每天的菜单、重新审视饮食，听男士说「睡眠不好不妨问医生」后，决定先去第4会场找医师咨询。", t:"（同上・市の健康イベント）質問２：女の人はまずどの会場に行くと言ってますか。 1.第1会場 2.第2会場 3.第3会場 4.第4会場"},

  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】あのう、渡辺さん。明日の午後のミーティングに出てもらえると助かるんですが。最もよい返事を選びなさい。", passage:"", opts:["午後ですか？かまいませんよ","ミーティングに出てくれるんですか？","じゃ、ミーティングに出るのはやめておきましょう"], ans:0, exp:"①「～てもらえると助かるんですが」＝您若能出席就帮大忙了（委婉请求），答应的回应是「午後ですか？かまいませんよ」（下午吗？没关系哦），第1项恰当。②考点：即時応答——使役受身的委托句须以接受作答。③排除：2把请求误听成对方在问自己；3是拒绝出席，与「助かる」的请求相悖。④翻译：发言：那个啊渡边，明天下午的会议您能出席的话就帮大忙了。恰当回应：下午吗？可以啊。", t:"あのう、渡辺さん。明日の午後のミーティングに出てもらえると助かるんですが。 1.午後ですか？かまいませんよ 2.ミーティングに出てくれるんですか？ 3.じゃ、ミーティングに出るのはやめておきましょう"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】何スマホ見てひとりでゲラゲラ笑ってるの？最もよい返事を選びなさい。", passage:"", opts:["え、つまらなそうに見えた？","いや、この動画おかしくて","そう、そんなに面白くないんだよね"], ans:1, exp:"①对方问「你怎么一个人对着手机哈哈大笑」，应回答原因——「いや、この動画おかしくて」（没，这视频太搞笑了），第2项恰当。②考点：即時応答——「なんで～の？」询问原因，答句给理由；「～くて」表原因。③排除：1对方是好奇不是觉得你无聊；3否定有趣与「ゲラゲラ笑っている」矛盾。④翻译：发言：干嘛呢一个人盯着手机傻笑？恰当回应：没，这视频太搞笑了。", t:"何スマホ見てひとりでゲラゲラ笑ってるの？ 1.え、つまらなそうに見えた？ 2.いや、この動画おかしくて 3.そう、そんなに面白くないんだよね"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】日曜の朝、雨降るんだって。出かけるまでに止めばいいけど。最もよい返事を選びなさい。", passage:"", opts:["雨、止まないと嫌だね","雨、そんな止んでじゃないの？","雨、気にならないんだね"], ans:0, exp:"①「出かけるまでに止めばいいけど」＝只要出门前雨停就行，顺势的回应是「雨、止まないと嫌だね」（雨不停可不行啊），第1项恰当。②考点：即時応答——「～ばいいけど」隐含「万一半途不停就糟了」，回应须同向担忧。③排除：2把陈述听成「正在下」的反问；3「你不在乎啊」与出门遇雨的关切相反。④翻译：发言：周日早上会下雨呢，只要出门前停了就行。恰当回应：雨要是不停就糟了呢。", t:"日曜の朝、雨降るんだって。出かけるまでに止めばいいけど。 1.雨、止まないと嫌だね 2.雨、そんな止んでじゃないの？ 3.雨、気にならないんだね"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】たまにね、おじいちゃんが生きているといいのにって思うんだ。最もよい返事を選びなさい。", passage:"", opts:["おじいちゃん、元気でよかったね","いいおじいちゃんだったんだね","おじいちゃんの体、心配だよね"], ans:0, exp:"①「おじいちゃんが生きているといいのに」＝（外公若还健在就好了）——说明爷爷已故、说话人怀念他；回应「おじいちゃん、元気でよかったね」（你爷爷身体硬朗真好啊）是对过往的同感追忆，第1项恰当。②考点：即時応答——「～ているといいのに」是对已不可能之事的愿望，答句应朝向怀念/同感。③排除：2「是位好爷爷」虽通顺，但与「若健在就好了」的虚拟语气接续不佳，标准答案为1（对其曾健康的追认）；3爷爷已去世，谈不上担心身体。④翻译：发言：我偶尔会想，爷爷要是还健在就好了。恰当回应：你爷爷那时候身体硬朗，真好啊。", t:"たまにね、おじいちゃんが生きているといいのにって思うんだ。 1.おじいちゃん、元気でよかったね 2.いいおじいちゃんだったんだね 3.おじいちゃんの体、心配だよね"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題4即時応答（3选1）", q:"【発言】学校、辞めるって決めた以上、早く先生にも話した方がいいよね。最もよい返事を選びなさい。", passage:"", opts:["決めたんだったら、そうしたほうがいいよ","やめるかどうか相談して決めるんだね","きちんと決めてからのほうが良くない？"], ans:0, exp:"①「決めた以上（は）」＝既然已经决定，回应「決めたんだったら、そうしたほうがいいよ」（既然定了那就那样做好了）承接同一前提，第1项恰当。②考点：即時応答——「～以上（は）」表既定事实＋「～たほうがいい」建议，答句须接受该建议。③排除：2把「已经决定」误作「还在商量」；3与「決めた以上」的既定前提矛盾。④翻译：发言：既然你决定退学了，还是早点跟老师说比较好吧。恰当回应：既然已经定了，那就那样做吧。", t:"学校、辞めるって決めた以上、早く先生にも話した方がいいよね。 1.決めたんだったら、そうしたほうがいいよ 2.やめるかどうか相談して決めるんだね 3.きちんと決めてからのほうが良くない？"},

  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題5综合理解（选项据原文补配）", q:"女の人はどこのお雑煮が食べたいですか。", passage:"", opts:["東部：醤油味で野菜や鶏肉が入る","西部：醤油味で鮭などの魚が入る","北部：のりだけのシンプルな味","南部：味噌味で野菜だけ"], ans:3, exp:"①第4项正确：女方说「うちは醤油味だから、味噌味のが食べてみな」，四个地区中味噌味的只有南部。②考点：問題5（综合理解）——先记住播报中「地区×味道×材料」的对照表，再听个人意愿。③排除：1、2是酱油味，她家已是酱油味；3北部只有海苔，不符合她「想尝味噌味」的意愿。④全文翻译：播报员介绍各地杂煮：东部酱油味放蔬菜鸡肉、西部酱油味放鲑鱼等鱼、北部只放海苔、南部味噌味只放蔬菜。男：种类真多，你想吃哪种？女：我家是酱油味的，想尝尝味噌味的。男：我喜欢清淡的，比起味噌更喜欢酱油，还想吃放鱼的。女：那清淡的话放海苔的也不错？男：嗯，好奇是好奇，可只有海苔……", t:"テレビのアナウンサーがお正月の料理について話しています。 アナウンサー：あと少しでお正月ですね。お正月の食べ物といえば、お雑煮ですが、スープの味や材料は、この地域の中でも場所によって違います。例えば、東部は醤油味で野菜や鶏肉が入っています。同じ醤油味でも、西部では鮭などの魚を入れます。これに対して野菜も魚も入っていないのは北部のお雑煮でのりだけが入っているシンプルな物です。お雑煮の味付けですが、醤油だけではありません。南部は味噌で味付けをします。材料は野菜だけです。さて、皆さんのお宅では、どんなお雑煮を食べていらっしゃいますか？ 男：へー、いろいろあるんだね。どれ食べてみたい？ 女：うーん、うちは醤油味だから、味噌味のが食べてみたいな。 男：僕はあっさりしてるのが好きなんだよね。だから味噌より醤油かな。それから魚が好きだから魚が入っているのが食べてみたいなあ。 女：そうなんだ。じゃ、あっさりした味付けなら、のりが入っているのもいいんじゃない？ 男：うーん、珍しいから気になるけど、のりしか入ってないんじゃねえ。 女：そう。 質問1：女の人はどこのお雑煮が食べたいですか？ 1.東部 2.西部 3.北部 4.南部"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題5综合理解（选项据原文补配）", q:"男の人はどこのお雑煮が食べたいですか。", passage:"", opts:["東部：醤油味で野菜や鶏肉が入る","西部：醤油味で鮭などの魚が入る","北部：のりだけのシンプルな味","南部：味噌味で野菜だけ"], ans:1, exp:"①第2项正确：男方说「あっさりしてるのが好き（味噌より醤油）、魚が入っているのも食べてみたい」——酱油味＋有鱼的正是西部。②考点：综合理解——把两条个人偏好（味付け＝醤油／材料＝魚）同时匹配到同一地区。③排除：1东部虽是酱油但只有蔬菜鸡肉，未含鱼；3北部只有海苔、他说「のりしか入ってないんじゃねえ」表示没兴趣；4是女方想吃的味噌味。④译文（要点）：见上——男方喜欢清淡口味、选酱油胜过味噌，又想吃有鱼的，故为西部（酱油＋鲑鱼等）。", t:"（同上・お雑煮）質問2：男の人はどこのお雑煮が食べたいですか？ 1.東部 2.西部 3.北部 4.南部"},

  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題1課題理解（选项据原文补配）", q:"女の人はこの後まず何をしますか。", passage:"", opts:["料理の予約をする","感謝のメッセージ用のカードを準備する","花束を準備する","スピーチを頼む"], ans:1, exp:"①第2项正确：男方拜托「とりあえずカードを準備してくれないかな？」女方答应「わかった」；料理预约定在下周出席者明确后、花束由男方当天准备、致辞由小林课长主动承担——女方首先要做的就是准备卡片。②考点：問題1（課題理解）——听清「誰が・何を・いつまでに」的委托与「任せて／わかった」的接受，注意多个动作的时间提示。③排除：1料理是「来週あたり」再定；3花束是「当日まで僕が準備する」；4致辞已有小林课长包揽。④全文翻译：男：下个月中川部长的退休派对，我把刻名字的玻璃杯委托给邻镇工厂了，大概两三周做好，做好后想让你去取。还有想请你先准备卡片，好收集营业部大家的感谢留言，花束我当天准备。女：知道了。男：谢谢。料理还没预约，等下周出席人数确定再说，也许有人忌口。女：对了，致辞说好要拜托人，怎么样了？男：小林课长主动说非他不可。女：那太好了。", t:"会社で男の人と女の人が話しています。女の人はこの後まず何をしますか？ 男：ね、来月の中川部長の退職パーティーの準備の件なんだけど、プレゼントは部長の名前を入れたグラスを隣町の工場にお願いしたんだ。２週間から３週間はかかるみたいで、出来上がったら受け取りに行ってほしいんだ。 女：うん、任せて。 男：あと営業部のみんなから感謝のメッセージを集めるのにとりあえずカードを準備してくれないかな？花束は当日まで僕が準備するから。 女：わかった。 男：ありがとう。料理の予約もまだなんだけど、それは来週あたり出席者がはっきりしてからのほうがいいかと思って。食べられないものがあるかもしれないしね。 女：そうだね。あとスピーチを頼むって話になってたけど、どうなってる？ 男：あ、それは是非俺がって小林課長が言ってて。 女：それはよかった。 女の人はこの後まず何をしますか？ 1.料理の予約をする 2.感謝のメッセージ用のカードを準備する 3.花束を準備する 4.スピーチを頼む"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題1課題理解（选项据原文补配）", q:"男の学生は何をしなければなりませんか。", passage:"", opts:["研究発表の順番とスケジュールを来週のゼミで決める","宿泊先を民宿に予約する","往復の交通手段を予約する","ポスターを作成する"], ans:2, exp:"①第3项正确：老师指出「往復の交通手段は大急ぎで押えとかないといけませんね」——日程安排要等下周一齐讨论（①不属于他个人眼下必办），住宿方面他叔父的民宿已搞定（③无须再订），故他必须马上办的是预订往返交通。②考点：課題理解——多人物、多动作并列时，用「既に済んでいる／来週に決める」排除，锁定「大急ぎで」的那一件。③排除：1是「来週のゼミの日にみんなで話し合いましょう」的集体事项；2叔父答应格安提供大房间，已解决；4原文未提海报。④全文翻译：男：先生，下个月东高原研修旅行的计划案您看了吗？女：看了。研究发表顺序和到达后的细排期看来需要在下周研讨课上大家一起商量。日子定在下月第三周周末了吧。男：大家只有这个周末能去。女：正好是红叶季又是旅游旺季，包车巴士很快会满，往返的交通手段得赶紧订下来。还有住宿也得快点预约。男：说到这个，我叔父在东高原开民宿，说那个周末可以便宜让我们住，还有大房间，大家能一起学习。女：那真是帮大忙了。", t:"男の学生と先生が話しています。男の学生は何をしなければなりませんか？ 男：先生、来月の東高原へのゼミ旅行の計画案なんですけど、見ていただけましたか？ 女：ええ、見ましたよ。研究の発表の順番とか到着してからの細かいスケジュールを組む必要がありそうだけど、来週のゼミの日にみんなで話し合いましょう。 男：わかりました。 女：それで日にちは来月第３週の週末になったんですね。 男：みんな行けるのはこの週末しかなくて。 女：ちょうどもみじの季節で観光シーズンだから貸切バスとはどこと早くいっぱいになっちゃいますよね。往復の交通手段は大急ぎで押えとかないといけませんね。 男：そうですね。 女：あと宿泊先も急いで予約しないと。 男：あ、それなんですけど、実は叔父が東高原で民宿やってるんですが、その週末、格安で泊まらせてくれるって言ってるんです。大部屋もありますのでみんなで勉強できますし。 女：それはありがたいですね。 男の学生は何をしなければなりませんか？ 1.研究発表の順番とスケジュールを来週のゼミで決める 2.宿泊先を民宿に予約する 3.往復の交通手段を予約する 4.ポスターを作成する"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題1課題理解（选项据原文补配）", q:"交流会で留学生は何をしますか。", passage:"", opts:["自分の国の伝統的な楽器を紹介する","自分の国のあいさつや簡単な会話を教える","日本と自分の国の文化の違いを紹介する","制服について話し合う"], ans:0, exp:"①第1项正确：老师说候选活动里「あいさつや簡単な会話」「文化の違い」以前做过，这次要换新的，故本次做「伝統的な楽器の紹介」；制服话题被校方婉拒（見送り）。②考点：課題理解——注意「以前やったことがあるので今回は違ったことをやりましょう」的排除句与「見送り」的否定。③排除：2、3都是「以前做过的」；4被中学校方要求「見送り」。④全文翻译：老师通知：下月去中学交流，上周大家提了几个候选：介绍本国传统乐器、教日语寒暄与简单会话、介绍日两国文化差异——这些都不错，但以前做过，这次做点不一样的，下周之前把要介绍的内容定下来。活动候选我们也和中学商量了，他们希望制服讨论这次先取消。", t:"大学で日本語の先生が話しています。交流会で留学生は何をしますか。 女：来月、中学校で行う交流会についてお知らせします。先週皆さんにいくつか活動の候補をあげてもらいましたが、自分の国の伝統的な楽器の紹介しましょう。自分の国のあいさつや簡単な会話を教えること、日本と自分の国との文化の違いの紹介、これらも面白いと思います。ただ、以前やったことがあるので今回は違ったことをやりましょう。来週までに紹介する内容を考えておいてください。活動の候補については中学校側とも相談したのですが、制服についての話し合いは見送りにしたいとお願いがありました。 交流会で留学生は何をしますか。 1.自分の国の伝統的な楽器を紹介する 2.自分の国のあいさつや簡単な会話を教える 3.日本と自分の国の文化の違いを紹介する 4.制服について話し合う"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題1課題理解（选项据原文补配）", q:"男の学生はどうやってイヤホンを捨てますか。", passage:"", opts:["資源ごみとして出す","燃えないごみとして出す","大学近くの電気屋に持っていく","市役所などの回収専用箱に出す"], ans:3, exp:"①第4项正确：有线耳机可扔垃圾，但充电式不行；大学附近的电器店又不回收（「あそこの店はやってないって」），最终查到「この辺りの地域では市役所とかの公共施設に回収専用の箱」，男生也说「今日持っていくよ」。②考点：課題理解——方案被逐一否定后的最终结论才是答案。③排除：1充电式「ごみに出せないんじゃない？」被否定；2同被排除；3电器店不回收。④全文翻译：男：耳机坏了。女：无线的那种吧？男：嗯，换了新的，坏的打算扔掉，算资源垃圾还是不可燃垃圾？女：充电式的不能直接扔垃圾吧？啊，电器店也能回收。男：那拿到大学附近的店？女：查了，那家不做。这附近要在市役所等公共设施的专用回收箱投放。男：扔个东西也真麻烦，今天就拿去吧，谢谢。", t:"男の学生と女の学生が話しています。男の学生はどうやってイヤホンを捨てますか？ 男：イヤホンが壊れちゃったんだ。 女：あのコードのないのだよね？ 男：うん、そう。買い換えたから壊れたのはゴミに出すんだけど、資源ごみで出すのかな？それとも燃えないごみでいいのかな？ 女：充電するタイプだからごみに出せないんじゃない？あ、電気屋でも出せるよ。 男：そう、大学近くの電気屋に持って行こうかな。 女：えっと、検索してみるね。あそこの店はやってないって。この辺りの地域では市役所とかの公共施設に回収専用の箱が置いてあるみたい。 男：捨てるのも大変だな。今日持っていくよ。ありがとう。 男の学生はどうやってイヤホンを捨てますか？ 1.資源ごみとして出す 2.燃えないごみとして出す 3.大学近くの電気屋に持っていく 4.市役所などの回収専用箱に出す"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題2ポイント理解（选项据原文补配）", q:"女のタレントは釣りを始めたきっかけは何だったと言っていますか。", passage:"", opts:["テレビの釣り番組で見た姿に心を動かされた","祖父によく釣りをもらっていた","友達に一緒に釣りをするよう勧められた","本屋で釣りの雑誌を見た"], ans:0, exp:"①第1项正确：「たまたま釣りの番組を見たんです。そこで出ていた方が…生き生きしていて私も釣りがしたいって思ったのが始まりです」＝在电视上看到钓鱼节目、被那份生机勃勃打动才是起点。②考点：問題2（ポイント理解）——「きっかけ／始まり」一词定位；祖父是回忆、杂志是入门途径、邀请朋友是后来的事。③排除：2祖父钓鱼是联想到的往事，非起点；3劝朋友是最近才有的行为；4杂志是在决定学钓之后才买的。④全文翻译：男：太田女士是因为谁的影响开始钓鱼的吗？女：我那时正找能在户外做的爱好，偶然看到钓鱼节目。节目里的人在小港口从岸上钓沙丁鱼、竹荚鱼，那副样子生机勃勃，我当下就想「我也要钓」——这就是开始。我小时候祖父爱钓鱼，常带鱼回来，那时也想起了这件事。以前我没钓过，起初连新手该备什么装备、去哪好都不知道，后来在书店找到钓鱼杂志，也知道了好的钓具店，最近还劝朋友一起钓呢。", t:"テレビで男のアナウンサーが女のタレントにインタビューしています。女のタレントは釣りを始めたきっかけは何だったと言っていますか？ 男：太田さんはどなたかの影響で釣りを始められたのですか？ 女：何か外でできる趣味を探していた時にたまたま釣りの番組を見たんです。 男：ええ。 女：そこで出ていた方が小さい港で岸の上からアジやイワシを釣ってたんですが、その姿がすごく生き生きしていて私も釣りがしたいって思ったのが始まりです。私が幼い頃に祖父が釣り好きだったんですが、魚を釣ってよく持ってきてくれたことも思い出しました。 男：そうですか。 女：以前は自分で釣りをしたことがなくて、初めは初心者向けの道具やどんな場所がいいかも分からなかったんですけど、本屋で釣りの雑誌を見つけて、いい釣り道具のお店も分かりました。最近では友人に一緒に釣りをしようと勧めています。 女のタレントは釣りを始めたきっかけは何だったと言っていますか？ 1.テレビの釣り番組で見た姿に心を動かされた 2.祖父によく釣りをもらっていた 3.友達に一緒に釣りをするよう勧められた 4.本屋で釣りの雑誌を見た"},
  {type:"listen", src:"N2真题听力原文·2026年7月（爱心日语整理）·問題2ポイント理解（选项据原文补配）", q:"旅館の部屋にお菓子が置いてある1番の理由は何だと言っていますか。", passage:"", opts:["旅の疲れを取ってもらうため","もてなしの気持ちを伝えるため","売店のお菓子を買わせるため","空腹で入って体調を崩すのを防ぐため"], ans:3, exp:"①第4项正确：虽然提到消除疲劳、传达待客之心、也有客人在卖店买作特产，但说话人明确点出「実は温泉に入る前に何か口にしてほしいという意図があるんです。というのは空腹で入ると貧血や目眩を起こしかねません。…とにかくそれを防ぎたいからなんです」＝最首要的理由是防止空腹泡温泉引发晕眩。②考点：ポイント理解——抓「1番の理由」「実は～意図」「とにかく～たいから」这些提示首要目的的表达。③排除：1、2是客人反馈的附带效果；3是顺带的销售结果，不是摆放的目的。④全文翻译：我们是主打温泉的旅店，每个房间都会免费放上当地点心。客人很高兴，说甜食能消除旅途疲劳、也传达了待客的心意；我们在卖店也卖同样的点心，很多人买作特产。其实我们的用意是希望客人泡温泉前先吃点什么——空腹入浴可能导致贫血、眩晕，为的就是防这个。希望能让客人尽兴享受本店。", t:"ラジオで旅館の経営者が話しています。旅館の部屋にお菓子が置いてある1番の理由は何だと言っていますか？ うちは温泉が自慢の旅館です。各お部屋にサービスで地元のお菓子を置いております。甘いもので旅の疲れが取れるとか、もてなす気持ちが伝わるなどとお客様から喜んでいただいております。売店で同じお菓子を販売しておりますが、お土産として買ってくださるお客様も多いです。このお菓子、実は温泉に入る前に何か口にしてほしいという意図があるんです。というのは空腹で入ると貧血や目眩を起こしかねません。体調を崩す、とにかくそれを防ぎたいからなんです。お客様には当旅館を存分に楽しんでいただきたいです。 旅館の部屋にお菓子が置いてある1番の理由は何だと言っていますか？ 1.旅の疲れを取ってもらうため 2.もてなしの気持ちを伝えるため 3.売店のお菓子を買わせるため 4.空腹で入って体調を崩すのを防ぐため"}
];

